(window.RAGHIB_FULL = window.RAGHIB_FULL || {})["2-10"] = [{"a": [243], "v": 1, "p": 499, "ev": 1, "ep": 501, "sid": 500, "t": "قوله تعالى:\n﴿أَلَمۡ تَرَ إِلَى ٱلَّذِينَ خَرَجُواْ مِن دِيَٰرِهِمۡ وَهُمۡ أُلُوفٌ حَذَرَ ٱلۡمَوۡتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُواْ ثُمَّ أَحۡيَٰهُمۡۚ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ﴾⟪2:243⟫\nالآية: (243) - سورة البقرة.\nرأيت: تتعدى نفسه دون الجار، لكن لما استعير قولهم ﴿أَلَمۡ تَرَ﴾⟪2:243⟫ لمعنى: (ألم تنظر) عدى تعديته وفائدة استعارته أن النظر قد يتعرى عن الرؤية، فإذا أريد الحث على نظر ناتج لا محالة للرؤية استعيرت له، وقل ما استعمل دلك في غير التقرير، ولا يقال: رأيت إلى كذا، وكما أن الرؤية ضربان، رؤية بصر، ورقية بصيرة، كذا أيضا النظر والإبصار، وألوف جمع ألف كشخوص، وعيون وقيل جمع ألف كحمول، وحلوم، وروي في الخبر أن قوما من بني إسرائيل خرجوا من ديارهم- تفاديا من الطاعون فأماتهم الله، ثم أحياهم ليعرفهم عيانا تحقيق مادل عليه قوله: ﴿قُل لَّن يَنفَعَكُمُ ٱلۡفِرَارُ إِن فَرَرۡتُم مِّنَ ٱلۡمَوۡتِ أَوِ ٱلۡقَتۡلِ﴾⟪33:16⟫ وقوله: ﴿أَيۡنَمَا تَكُونُواْ يُدۡرِككُّمُ ٱلۡمَوۡتُ﴾⟪4:78⟫ وقوله: ﴿إِذَا جَآءَ أَجَلُهُمۡ فَلَا يَسۡتَـٔۡخِرُونَ سَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ﴾⟪10:49⟫⟦1:500⟧، وقوله: ﴿لَا تَكُونُواْ كَٱلَّذِينَ كَفَرُواْ وَقَالُواْ لِإِخۡوَٰنِهِمۡ إِذَا ضَرَبُواْ فِي ٱلۡأَرۡضِ أَوۡ كَانُواْ غُزّٗى لَّوۡ كَانُواْ عِندَنَا مَا مَاتُواْ وَمَا قُتِلُواْ﴾⟪3:156⟫، وقوله: ﴿وَهُمۡ أُلُوفٌ﴾⟪2:243⟫ تنبيه أن الكثرة والتعاضد وإن كانا نافعين في دفع الأزمات الدنيوية، فليس بمعنية في الأمور الإلاهية، فمن جعل ذلك جمع ألف، فنظر منه إلى نحو ما قال الشاعر:\nألم تر أن جمع القوم يخشى ..\nوأن حريم واحدهم مباح\nومن جعله جمع ألف، فنظر إلى نحو قولهم: \" لن يعجز القوم إذا تعاونوا \" ومن جعله جمع ألف، فقد قيل: كان عددهم أربعة آلاف عن السدي، وقيل، كانوا أكثر من عشرة آلاف عن ابن عباس والحسين والضحاك، وهو الأصح، لأن ذلك جميع للكثير ولو كانوا أقل من عشرة لقتل آلاف، وقيل: معنى أماتهم: ذللهم تذليلا يجري مجرى الموت فلم تغن عنهم كثرتهم وتظاهرهم من شيئا، ثم أحياهم، أي أعانهم وخلصهم ليعرفوا قدرة تعالى في أنه يذل من يشاء، ويعز من يشاء، وتسمية الشدائد موتا، لكونها أعظم الموتين، كما قال الشاعر:\nليس من مات فاستراح بميت ..\nإنما الميت ميت الأحياء\nوقيل: أشد من الموت ما يتمنى له الموت، وقيل: عنى بالموت الجهل، والحياة العلم، وقال ابن عباس في قوله: ﴿أَوَمَن كَانَ مَيۡتٗا فَأَحۡيَيۡنَٰهُ﴾⟪6:122⟫ أي: جاهلا فعلمناه كما يحيا الجسد بالروح، ووصل ما أراهم من الآية العظيمة من إحيائهم بذكر ماله عليهم من النعمة وقلة شكرهم له ..\n، وقوله:\n⟦1:501⟧\n﴿وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ﴾⟪2:243⟫ كقوله: ﴿وَقَلِيلٞ مِّنۡ عِبَادِيَ ٱلشَّكُورُ﴾⟪34:13⟫، لكنه أبلغ في الذم، لأنه نفى وقوع شكر منهم وشكور هنا مبالغة، وقد لا يكون شكورا من كان شاكرا ..\nإن قيل: لم أعيد ذكرا الناس ولم يقل: (ولكن أكثرهم)؟\nقيل: لأن الناس في الأول عام لكون نعمته على جميعهم، وفي الثاني خاص للمكلفين، لأنه لا يلزم شكرهم غيرهم، فكأنه قيل: ذو فضل على جميع الناس، ولكن أكثر المكلفين لا يشكرون ..\nإن قيل: لم خص النبي - ص - الله بهذا الخطاب، فقال: ﴿أَلَمۡ تَرَ﴾⟪2:243⟫ وقال: ﴿أَلَمۡ تَرَوۡاْ كَيۡفَ خَلَقَ ٱللَّهُ سَبۡعَ سَمَٰوَٰتٖ طِبَاقٗا﴾⟪71:15⟫؟\nقيل: لأن ذلك لما كان من الاعتبارات التي تخفي إلا على ذوي البصائر من الأنبياء ومن يدانيهم في العلم ولم تكن من المحسوسات المشاهدة، وخصه بالخطاب، وفي الآية الأخرى ونظائرها لما كانت من الأمور المحسوسة عمهم بالخطاب."}, {"a": [244], "v": 1, "p": 501, "ev": 1, "ep": 502, "sid": 502, "t": "قوله - عز وجل:\n﴿وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ﴾⟪2:244⟫ سورة البقرة الآية (244) ..\nقل: تقديره (وقيل لهم بعد ذلك: ﴿وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ﴾⟪2:244⟫، ولفظ الحكاية مقدر، وقيل: إن ذلك خطاب منه تعالى لهذه الأمة، وأنه لما قرر بالآية المتقدمة في أنفسهم أن الفرار لا يزيد في الأجل، حثهم بهذه على المجاهدة في سبيله، ولم يعن الأعداء المجاهدين فقط بل عناهم وأقرب الأعداء إلى الإنسان وأصعبها دفاعا وأكثرهم أذى الهوى المدلول عليه بقوله عليه الصلاة والسلام: \" جهادك هواك \"،\n⟦1:502⟧\nوقوله: «أعدي عدوك نفسك التي بين جنبيك» وقوله لما رجعوا من تبوك: \" جئتم من الجهاد الأصغر إلى الجهاد الأكبر \" وقال: \" جاهدوا أهواءكم كما تجاهدون أعداءكم \" وصعوبة مجاهدته أنه عدو يخفي وتخفى مكائده، ونحو هذا نظر الشاعر حيث قال:\nرمتني بنات الدهر من حيث لا أرى ..\nفكيف بمن يرمي وليس برامي\nوعلى هذا قولخ - عز وجل: ﴿وَجَٰهِدُواْ فِي ٱللَّهِ حَقَّ جِهَادِهِۦۚ﴾⟪22:78⟫، وقوله ﴿وَٱلَّذِينَ جَٰهَدُواْ فِينَا لَنَهۡدِيَنَّهُمۡ سُبُلَنَاۚ﴾⟪29:69⟫."}, {"a": [245], "v": 1, "p": 502, "ev": 1, "ep": 504, "sid": 503, "t": "قوله - عز وجل:\n﴿مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا فَيُضَٰعِفَهُۥ لَهُۥٓ أَضۡعَافٗا كَثِيرَةٗۚ وَٱللَّهُ يَقۡبِضُ وَيَبۡصُۜطُ وَإِلَيۡهِ تُرۡجَعُونَ﴾⟪2:245⟫ الآية (245) - سورة البقرة.\nالقرض: القطع بالناب، والمقراض، واستعير لصنعة الشعر استعارة اللوك والمضغ في نحو قول بعضهم:\n⟦1:503⟧\n\" قد لاكه ومضغه من هو أشد لوكا ومضغا منك \" هذا إذا اعتبرته بقرض الأسنان، فأما إذا اعتبرته بقرض المقراض، فاستعارته كاستعارة الحوك والخياطة والإلباس، وسمي ما بذل بعوض قرضا، وما بذلك بغير عوض قرضا، وسمي عروض الدنيا قروضا، كما سميت عواري، والضعف تركب قدر من متساويين، أو يقال مثلا الشيء في المقدار، وكل واحد ضعف الآخر إذا أخذ، وقول الشاعر:\n\" جزيتك ضعف الود \" أي مثلي ودك في القدر، وضعفا الشيء مثله ثلاث مرات، إلا أنه إذا قيل: ضعفان، فقد يطلق على الاثنين المثلين في القدر من حيث أن كل واحد يضعف الآخر كما يقال الزوجان، ويكون كل واحد زوجا للآخر ..\nإن قيل: الضعف والضعف يشتركان في الاشتقاق، قيل: كلاهما اعتبر فيه معنى المماثلة في القدر، إلا أنه جعل الضعف لما يزاد عليه، والضعف لما ينقص منه، واستعمل فيهما أضعفت، وضعفت، وإن كان التشديد في الضعف أكثر، وضاعفت في الضعف لا غير، وفرق بينهم تضاعف وتضعف، فقال التضعيف لما جل مثلين، والمضاعفة لما زيد عليه أكثر من ذلك، ولهذا قال أكثرهم (فيضاعفه) بالألف، ولما حث الله على المجاهدة في سبيله وذلك ببذل المال والبدن والنفس سمى ذلك قرضا كما سماه بيعا واشتراء في قوله تعالى: ﴿إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم﴾⟪9:111⟫ الآية وسماه إحسانا في قوله: (واحسنوا) كل ذلك استعطافا لعبده واستلطافا، وسمع أعرابي قوله تعالى: ﴿مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا﴾⟪2:245⟫ فقال \" أعطانا فضلا، وسألنا منه قرضا ليرد إلينا أكثر وأوفر منه، إنه لكريم \" وسمع ذلك أبو الدحداح، فسأل النبي - صلى الله عليه وسلم إن تصدقت بحديقتي أفلي مثله في الجنة؟ قال: نعم.\nقال: ومعي أم الدحداح ودحداح؟ قال: نعم، وكان له حديقتان، فتصدق بأفضلهما ..\n⟦1:504⟧\nإن قيل: بذل النفس كيف يصح أن يقال له قرض؟\nقيل: استعمال ذلك فيه كاستعمال الجود، وقد قال أبو الدرداء \" أقرض من عرضك ليوم فقرك \" وفي قوله: ﴿حَسَنٗا﴾⟪2:245⟫ إشارة إلى كل ما يصون الإفضال عما يشينه من منة ومراءاة وغير ذلك وقوله ﴿يَقۡبِضُ وَيَبۡصُۜطُ﴾⟪2:245⟫ قيل: \" يسلب تارة، ويعطي تارة \"، ونحوه نظر من قال: فكيف يوفيه وثانية هاديه، وقيل: يسلب قوما ويعطي قوما، ونحوه نظر الشاعر في قوله:\nويسلب قوما ويثري آخرين ..\nبه الله من ذا يستعمر وباري\nوقيل: يقتر ويوسع، وقيل: يقبض الصدقات ويخلف البدل مبسوطا أن كثيرا، وقيل: يضيق صدور قوم ويشرح صدور آخرين، كقوله : ﴿فَمَن يُرِدِ ٱللَّهُ أَن يَهۡدِيَهُۥ يَشۡرَحۡ صَدۡرَهُۥ لِلۡإِسۡلَٰمِۖ وَمَن يُرِدۡ أَن يُضِلَّهُۥ يَجۡعَلۡ صَدۡرَهُۥ ضَيِّقًا حَرَجٗا﴾⟪6:125⟫، وقوله: ﴿وَإِلَيۡهِ تُرۡجَعُونَ﴾⟪2:245⟫ وقد تقدم الكلام فيه، وذكره ها هنا توعد .."}, {"a": [246], "v": 1, "p": 504, "ev": 1, "ep": 507, "sid": 505, "t": "قوله - عز وجل:\n﴿أَلَمۡ تَرَ إِلَى ٱلۡمَلَإِ مِنۢ بَنِيٓ إِسۡرَٰٓءِيلَ مِنۢ بَعۡدِ مُوسَىٰٓ إِذۡ قَالُواْ لِنَبِيّٖ لَّهُمُ ٱبۡعَثۡ لَنَا مَلِكٗا نُّقَٰتِلۡ فِي سَبِيلِ ٱللَّهِۖ قَالَ هَلۡ عَسَيۡتُمۡ إِن كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ أَلَّا تُقَٰتِلُواْۖ قَالُواْ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِي سَبِيلِ ٱللَّهِ وَقَدۡ أُخۡرِجۡنَا مِن دِيَٰرِنَا وَأَبۡنَآئِنَاۖ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ تَوَلَّوۡاْ إِلَّا قَلِيلٗا مِّنۡهُمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ﴾⟪2:246⟫ الآية: (246) - سورة البقرة.\nقوله عز وجل:\n﴿أَلَمۡ تَرَ إِلَى ٱلۡمَلَإِ مِنۢ بَنِيٓ إِسۡرَٰٓءِيلَ﴾⟪2:246⟫ إلى الملأ جماعة شريفة، وذلك اعتبار بالامتلاء كأنهم يملون العين رواء ومنه قيل: شاب مالئ العين، ومالأته: عافيته: أي صرت من ملائه أي جمعه، كقولك: شايعته أي: صرت من شيعته، وفلان ملئ بكذا من الامتلاء، وعلى الوفاء، وهو تمام العهد، واشتقاق\n⟦1:505⟧\nضده وهو العذر، يدل على ذلك لأنه الترك، ويعني: \" أحسنوا أملاءكم \"، أي أخلاقكم،\nوقال الشاعر:\n\" فقلنا أحسني ملأ جهينا \"، فكأنه سمي الخلق بذلك لكونه مليا بارا، في ذاته وعلى ذلك قال الشاعر:\nكل امرئ يبدي الذي في خلقه\nوقال: كل امرئ راجع يوما بشهية\nوالملك لمن جمع أربعة معان:\n\" العلم، والقدرة، والسياسة، وعددا يسويهم \"، وبيان ذلك أن الأمر بالعلم مدبر، وبالقدرة ينفذ، وبالسياسة ينظم، وبالجمع بحفظ، ولهذا كان الله الملك الحق، ومن عدله فكالظل له، ولهذا قال: \" السلطان ظل الله في الأرض \" أي خليفته، ومحفوظة كالظل الذي يظل، ولا يصح استحقاقه إلا لمن قام بحقه على مقتضى الشرع ولأجل تعذر القيام بذكره التسمية به، لأن المتسمي بالملك ما لم يوف حقه لابس ثوبي زور، وتكلف للناس التقول به وسألهم إياه الملك ليقابلوا معه لعلمهم أن منزلة الملك من الرعية منزلة الرأس من الجسد الذي لا قوام له إلا به.\n⟦1:506⟧\nوعلى ذلك قال الشاعر:\nكأن الخلق ركب في مثال ..\nله جسد وأنت عليه رأس\nوقوله: (يقاتل) متى جزم، فجواب، وإذا رفع فاستئناف، وقرئ (يقاتل) على وصف الملك، وقوله: ﴿هَلۡ عَسَيۡتُمۡ إِن كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ﴾⟪2:246⟫ أي: هل طمعتم في أنفسكم أن تقوم بذلك وأن لا تجن؟ قالوا: وما لنا ألا نقاتل؟ أنكروا أن يكون منهم تضجيع في قتال أعدائهم، فجعل حجتهم شيئين هما غاية ما يحنق، وهو انزعاجهم عن مقارهم الذي هو شريك القتل، وقيل الولد الذي هو أصعب على الإنسان من قتل نفسه، وفي حكاية ذلك إشارة إلى ذمهم من وجهين أحدهما أنهم قالوا: أن تكلفوا، وقد قيل: فلما قام الإنسان بواجب التزامه، ابتدأ ولهذا لما روجع النبي - صلى الله عليه وسلم - في الحج، فقيل: ألعامنا هذا؟ أم للأبد؟\nقال: بل للأبد\n⟦1:507⟧\nوذم الله (بني إسرائيل) في التزامهم الرهبانية، ثم قصروا فيها، والثاني: أنهم لم يلزموا القتال كما يجب أن يلزم، فإن المقاتلة في سبيل الله يجب أن لا يكون لها سمعة واجتلاب ثناء أو شفاء مغيطة وكذا يجب أن تكون سائر الأفعال المحمودة وهم لما قالوا: ﴿وَمَا لَنَآ أَلَّا نُقَٰتِلَ﴾⟪2:246⟫ قصدوا شفاء الغيظ لا ائتمار الرب، فعلم أنهم لا يصبرون في مواطن الحق على ما يجب.\nإن قيل: لم أدخل (أن) في قوله: ﴿وَمَا لَنَآ أَلَّا نُقَٰتِلَ﴾⟪2:246⟫ ولم يدخله في قوله: ﴿وَمَا لَكُمۡ لَا تُؤۡمِنُونَ﴾⟪57:8⟫؟\nقيل: إن قولك (مالك، ومالنا) تجئ مرة للإنكار وعليه قوله: ﴿وَمَا لَكُمۡ لَا تُؤۡمِنُونَ﴾⟪57:8⟫ في موضع الحال نحو قوله تعالى: ﴿فَمَا لَهُمۡ عَنِ ٱلتَّذۡكِرَةِ مُعۡرِضِينَ﴾⟪74:49⟫ والثاني بمعنى: (ما منع) وعليه هذه الآية، فلابد إذن من \" أت لا \" تقديره: (ما منعنا من ترك القتال قال أبو العباس: \" ما: نفي ها هنا، كأنه قيل: ليس لنا أن لا نقاتل \" وقال الأخفش: أن زائدة، ويجوز أنه أدخل (أن) في قوله: ألا نقاتل لكون القتال مستقبلا، ولم يدخل في قوله: ﴿وَمَا لَكُمۡ لَا تُؤۡمِنُونَ﴾⟪57:8⟫ لكونه حالا، لأن \" أن \" لأحد المعدومين .."}, {"a": [247], "v": 1, "p": 507, "ev": 1, "ep": 509, "sid": 508, "t": "قوله - عز وجل:\n﴿وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ٱللَّهَ قَدۡ بَعَثَ لَكُمۡ طَالُوتَ مَلِكٗاۚ قَالُوٓاْ أَنَّىٰ يَكُونُ لَهُ ٱلۡمُلۡكُ عَلَيۡنَا وَنَحۡنُ أَحَقُّ بِٱلۡمُلۡكِ مِنۡهُ وَلَمۡ يُؤۡتَ سَعَةٗ مِّنَ ٱلۡمَالِۚ قَالَ إِنَّ ٱللَّهَ ٱصۡطَفَىٰهُ عَلَيۡكُمۡ وَزَادَهُۥ بَسۡطَةٗ فِي ٱلۡعِلۡمِ وَٱلۡجِسۡمِۖ وَٱللَّهُ يُؤۡتِي مُلۡكَهُۥ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ﴾⟪2:247⟫ الآية (247) - سورة البقرة.\nكان بنو إسرائيل اعتقدوا أن الملك يستحق بالوراثة وكثرة المال، وكان فيهم أسباط ملوك، فلما أنبأهم نبيهم أن الله بعث لهم طالوت ملكا، ولم يكن من بيت الملك، ولا كان ذا مال، استعظموا، فراجعوه وقالوا: ﴿أَنَّىٰ يَكُونُ لَهُ ٱلۡمُلۡكُ عَلَيۡنَا﴾⟪2:247⟫ وكان ذلك منهم خطأ من وجهين:\n⟦1:508⟧\nالأول:\nلما قال الشعر:\nوما الحسب الموروث لا در دره ..\nبمحتسب إلا بآخر مكتسب\nإذا الغضن لم يثمر وإن كان شعبة ..\nمن الثمرات اعتده الناس في الحطب\nوقال بعض الملوك:\nإن ولد مني جاهل فعدوه حمارا، وإياكم أن تراعوا نسبه، فتفوضوا الأمر إليه، وتعتمدوا في المملكة عليه، والثاني: أن المال ليس بضروري في الملك وأعيان الخلفاء الراشدين والأمراء العادلين كأن عناهم القناعة دون الثروة، فبين تعالى بقوله: ﴿إِنَّ ٱللَّهَ ٱصۡطَفَىٰهُ عَلَيۡكُمۡ﴾⟪2:247⟫ أن فيه الخصال التي هي قانون في استحقاق الملك وبيانه أن الملك يستحق في أن يكون الإنسان من عنصر صالح سواء كان من بيت الملك قيل أو لم يكن.\n، وأن يكون ذا علم بسياسة نفسه وأهله من رعيته، وأن يكون في جسمه كامل الخلقة، شديد القوة، ذا سلامة من العاهات الشائنة، وذكر أنه قد آتاه كل ذلك، ثم قال: ﴿وَٱللَّهُ يُؤۡتِي مُلۡكَهُۥ مَن يَشَآءُۚ﴾⟪2:247⟫ تنبيها أنه هو المختص بإيتاء الملك لعلمه يمن يستحقه، ولذلك أمرنا بالاستسلام له في ذلك، فقال: ﴿قُلِ ٱللَّهُمَّ مَٰلِكَ ٱلۡمُلۡكِ تُؤۡتِي ٱلۡمُلۡكَ مَن تَشَآءُ﴾⟪3:26⟫ فقرن ذلك بالأمور التي يختص هو بها، وهي: إخراج الحي من الميت والميت من الحي، وإيلاج الليل في النهار، وإيلاج النهار في الليل، وإعطاء الرزق، ثم قال: ﴿وَٱللَّهُ وَٰسِعٌ عَلِيمٞ﴾⟪2:247⟫ أي الذي أعطاه الملك هو ذو سعة في المال، وعالم بالأشياء - تنبيها أنه إن احتاج إلى المال في ملكه حوله، وقوله: ﴿عَلِيمٞ﴾⟪2:247⟫ أي عالم بمن يؤتيه الملك، كقوله: ﴿ٱللَّهُ أَعۡلَمُ حَيۡثُ يَجۡعَلُ رِسَالَتَهُۥۗ﴾⟪6:124⟫.\n⟦1:509⟧"}, {"a": [248], "v": 1, "p": 509, "ev": 1, "ep": 511, "sid": 510, "t": "قوله - عز وجل:\n﴿وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ءَايَةَ مُلۡكِهِۦٓ أَن يَأۡتِيَكُمُ ٱلتَّابُوتُ فِيهِ سَكِينَةٞ مِّن رَّبِّكُمۡ وَبَقِيَّةٞ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَٰرُونَ تَحۡمِلُهُ ٱلۡمَلَٰٓئِكَةُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ﴾⟪2:248⟫ الآية (248) - سورة البقرة.\nالبقية من البقاء، والبقاء ثبات الشيء على حالته الأولى، لكن البقية صارت لبعض حمله لم يتعين حكمه بتعين المحمولات، فاستعمل فيما يحمل على الظهر، وفي الماء إلي في السحاب، والولد الذي تحمله المرأة في البطن، وتعورف في البرق، وتسميته بذلك استصحابا لحمل الأم أيا، أو لأنه يحمل باليد لصغره، وخص الحمالة بما يحمل به السيف على بناء العلاقة، والمحمل لما تركته الناس، وخص الحمالة بالفتح لما يتحمله قوم من الدية والحميل تارة استعمل في الكفيل، وهو بمعنى فاعل، وتارة في المحمول من بلد إلى بلد، فسمى الغريب، وعثاء السيل به والحملوة من الإبل لما يحمل عليه وعلى ما ساقويه وركوبه وذكر منهم ما خص الله به \" طالوب \" من كرامته وما هو آية من الله - عز وجل - كالمعجزة لملكه، واختلف في التابوت فمنهم من قال: كان منحوتا من الخشب فيه شيء مسمى بالسكينة تسكن بها قلوب القوم الذي كان معهم وبقايا رضاض اللوح الذي كان فيه التوراة، وقنا كان علي [عجلة بين ثورين] يسوقهما الملائكة، وقيل: بل الملائكة تحمله في الهواء وهم يرونه، وقيل كان هذا التابوت مع يوشع، ففقد في التيه، ثم رده الله عز وجل: إلى طالوت، وقيل: بل كان قد سلبته العمالقة، فدفنوه في منزله، وإلى هذا ذهب عامة الصحابة والتابعين فيما دل عليه ظاهر قولهم حتى قال مجاهد: السكينة شيء كان له رأس كرأس هره، وله جناحان، وقال بعض المفسرين: التابوت\n⟦1:510⟧\nإشارة إلى القلب، والسكينة إلى ما فيه من العلم والإخلاص والإيمان وذكر الله الذي تطمئن به القلوب، قال: وسمي القلب سفط العلم وبيت الحكمة وتابوته، ورعاه وصندوقه، وعلى هذا يقال: (اجعل سرك في وعاء غير سرب، وفي بيت معلق الرتاج، ووعاء موثق الأشراج)، قال: وجعل آيته أن صير قلبه مقر العلم، ومجمع السكنية بعد أن لم يكن له ذلك، وعلى ذلك تسميته بالتابوت سمي عمر ابن مسعود - رضي الله عنهما كنيفا ملئ علما، وقال هذا القائل ما روي عن علي - عليه السلام، ورضي الله عنه: أن السكينة ريح هفافة لها وجه كوجه الإنسان، فإشارة إلى الروح أو إلى الملائكة، ولهذا روي \" كان روحا \" من الله عز وجل - يكلمهم عند وقوع الاختلاف، ويسكنهم عند القتال والله أعلم بالحقائق.\n⟦1:511⟧"}, {"a": [249], "v": 1, "p": 511, "ev": 1, "ep": 513, "sid": 512, "t": "قوله - عز وجل:\n﴿فَلَمَّا فَصَلَ طَالُوتُ بِٱلۡجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبۡتَلِيكُم بِنَهَرٖ فَمَن شَرِبَ مِنۡهُ فَلَيۡسَ مِنِّي وَمَن لَّمۡ يَطۡعَمۡهُ فَإِنَّهُۥ مِنِّيٓ إِلَّا مَنِ ٱغۡتَرَفَ غُرۡفَةَۢ بِيَدِهِۦۚ فَشَرِبُواْ مِنۡهُ إِلَّا قَلِيلٗا مِّنۡهُمۡۚ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ قَالُواْ لَا طَاقَةَ لَنَا ٱلۡيَوۡمَ بِجَالُوتَ وَجُنُودِهِۦۚ قَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ ٱللَّهِ كَم مِّن فِئَةٖ قَلِيلَةٍ غَلَبَتۡ فِئَةٗ كَثِيرَةَۢ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ﴾⟪2:249⟫ الآية: (249) - سورة البقرة.\nالجند يقال للعسكر اعتبارا بالغلظة من الجند، أي الأرض الغليظة ثم يقال: لكل مجتمع جند، نحو: (الأرواح جنود مجندة .. )، والغرف تناول الماء، ويقال للمعترف غرفة، وللمرة غرفة، والغريف الماء المعرض للاغتراف، وتصور منه الرفع، فسمي العلية غرفة تشبيها بالمغترف، وبهذا النظر سمي مشربة، وسمي الغمام مادام عرفه كأنه لرطوبته معترف، وجوز الطريق وسطه، و (جاز منه) كأنه عبر الجوز، فكثر حتى صار الجايز لما لا يكره، وعلى نحوه قيل سائغ، وهو من ساغ الطعام في الحلق، وجاوز، وتجاوز استعير له هذا البناء، لتصور المكان متباعدا عن الإنسان تباعد لإنسان عنه، ولهذا قيل: سافر وتباعد والفئة فرقة من قولهم: فاءت رأسه، وقد تقدم أن أسماء الفرق كثيرا ما تشتق من الألفاظ المقتضية للقطع كالصرمة، والقطيع والطامة، وما القوة بالمحمول، ويستعمل في قوة الحيوان، وأكثر ما يقال في الأثقال الجسيمة، وإذا قيل في غيرها، فعلى التشبيه، وروي في الخبر أن طالوت لم يكن يثق بقومه، فأراد أن يمتحنهم، وكان قد سار بهم مفازة لم يجدوا فيها ماء، فانتهوا إلى نهر من الأردن وفلسطين، فامتحنهم به ..\n⟦1:512⟧\nإن قيل: فكيف قال: ﴿إِنَّ ٱللَّهَ مُبۡتَلِيكُم﴾⟪2:249⟫ فنسب ذلك إلى الله عز وجل ..\nقيل: يجوز أن يكون الله تعالى ألقى ذلك في روعه كإلقاء الوحي في روع أم موسى، ويجوز أن يكون قد أخبره نبي زمانه عن الله، ويجوز أنه نسبه إلى الله لما قصد به وجهه وإن لم يكن الله قد أخبره به، كقوله: ابتلانا الله بكذا، وبين تعالى أن أكثرهم لم يأتمروا له، وقال بعضهم: \" إن ذلك جعله الله مثالا لهم \"، ومثلا مضروبا للدنيا وأتباعها وأن من يتناول منها قدر ما يتبلغ به اكتفى واستغنى وسلم منها ونجا، ومن تناول منها فوق ذلك ازداد عطشا، وعلى هذا قيل: \" الدنيا كالماء المالح \"، من ازداد منها شربا ازداد عطشا، وإلى هذا أشير في الخبر المروي \" أن الله - عز وجل - إذا سأله عبد شيئا من عروض الدنيا أعطاه، وقال له: خذه وضعفه حرصا \" وإياه عني النبي - عليه الصلاة والسلام بقوله: (لو أن لابن آدم واديين ذهب، ابتغى إليهما ثالثا، ولا يملأ جوف ابن آدم إلا التراب)، وقوله: ﴿وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ﴾⟪2:249⟫ يجوز أن يكون معطوفا على (هو ومعه) من صلة (آمنوا)، ويجوز أن يكون: (الذين آمنوا، ومعه) خبره، وهو الأجود، لأن الأظهر في قوله: ﴿لَا طَاقَةَ لَنَا﴾⟪2:249⟫ إن ذلك حكاية عمن شربوا، وإليه ذهب ابن عباس والسدي وقالا: \" هم أهل الكفر لا الذين آمنوا \"، وقال الحسن وقتادة وابن زيد: \" الذين قالوا: \" لا طاقة لنا \" هم المؤمنون \" وقوله: ﴿قَالَ ٱلَّذِينَ يَظُنُّونَ﴾⟪2:249⟫ ظن ها هنا هو المفسر باليقين عند أهل اللغة، وهو المعرفة الحاصلة عن امارة قومه، ويدل على ذلك استعمال أن المشددة أو المخففة منها، نحو: ﴿عَلِمَ أَن سَيَكُونُ مِنكُم مَّرۡضَىٰ﴾⟪73:20⟫ وإذا أريد الشك، استعمل معه (إن) التي تصحب المعدومين من الفعل، وقوله: (من) يجوز أن يكون استفهاما، وأن يكون خبرا وإن كان معنى الاستفهام يعود إلى معنى الخبر، ولكن متى قدر استفهاما نصب فيه إذا حذف عنه من، وإذا قدرته خبرا وجرت، وسكن منهم بأن عرفهم أن لا اعتبار بكثرة العدد وقلته وأحالهم على معرفتهم بالأعداد القليلة الغالية الكثيرة، وقد تقدم الكلام في قوله تعالى: ﴿وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ﴾⟪2:249⟫ ..\n⟦1:513⟧"}, {"a": [250], "v": 1, "p": 513, "ev": 1, "ep": 513, "sid": 514, "t": "قوله - عز وجل:\n﴿وَلَمَّا بَرَزُواْ لِجَالُوتَ وَجُنُودِهِۦ قَالُواْ رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ﴾⟪2:250⟫ الآية (250) - سورة البقرة.\nالبرز: المكان المرتفع، وبرز \" حصل فيه \"، وصار عبارة عن الظهور، وقيل للمشهور بالفضل: برز، و \" امرأة برزة \" قيل عفيفة، لأن رفعة المرأة بالعفة، لأن لفظ البرزة اقتضى ذلك، والأكثر أن البرزة هي التي لا تستقر، والفرغ: خلو المكان لما فيه، وخلو ذي الشغل من شغله، وسمي فرغ الدلو فرغا باعتبار انصباب الماء عنه، وضربه ضربة مفرغة لدم البدن، والثبات: اللزوم في المكان، وعنه استعير قول ثابت، أي صحيح لا يبطل، وفلان ثبت المقام لمن لا يبرح موقفه في الحرب منهزما، ونصر الله عنده قد يكون بزيادة قوته وجرأته، وبإلقاء الرعب في قلوب أعدائه، وغير ذلك، ولم يعن أنهم رغبوا إلى الله عز وجل - في ذلك بالقول فقط، فالقول ليس بمغن ما لم يعاضده فعل، ولا الفعل بمغن ما لم تعاضده النية، فالمعنى لما برزوا رغبوا إلى الله بمقالهم واجتهادهم ونياتهم أن يمدهم بالصبر، وتثبيت القدم والنصرة على الكفرة .."}, {"a": [251], "v": 1, "p": 513, "ev": 1, "ep": 515, "sid": 514, "t": "قوله تعالى:\n﴿فَهَزَمُوهُم بِإِذۡنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ وَٱلۡحِكۡمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّفَسَدَتِ ٱلۡأَرۡضُ وَلَٰكِنَّ ٱللَّهَ ذُو فَضۡلٍ عَلَى ٱلۡعَٰلَمِينَ﴾⟪2:251⟫ الآية (251) سورة البقرة.\nالهزم: دفع الشيء لليابس حتى يتحطم، كهزم الشن، وهزم الرعد مشبه به لصوت تكسره، وقيل أصابته هازمة دمر أي داهية كاسرة كقولهم فاقرة، والمهزام ما يحرك به للجمز والهمز يقاربه في الأمرين الكسر، والصوت والدفع صرف الشيء من مكان إلى مكان، أو عن حالة إلى حالة، ودافعت فلانا ودفعته أزعجته، وفلان مدفع مزعج عن مكانه أو بستانه، ووصف السيل الكبير بالدفاع، لدفع بعضه بعضا، بين تعالى أنه جمع لداود - عليه السلام - الملك والحكمة والنبوة، وهي أعظم فضيلة، إذ\n⟦1:514⟧\nلم تخص بمجموعها إلا بعض الأنبياء، وجعل لبعضهم النبوة دون الملك، وإن لم يخل أحد منهم من نصرته - لقوله تعالى:\n﴿إِنَّا لَنَنصُرُ رُسُلَنَا وَٱلَّذِينَ ءَامَنُواْ﴾⟪40:51⟫ وقال لموسى عليه الصلاة والسلام: ﴿سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجۡعَلُ لَكُمَا سُلۡطَٰنٗا﴾⟪28:35⟫ وقال: ﴿فَقَدۡ ءَاتَيۡنَآ ءَالَ إِبۡرَٰهِيمَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ﴾⟪4:54⟫ لقوله ﴿لَقَدۡ أَرۡسَلۡنَا رُسُلَنَا بِٱلۡبَيِّنَٰتِ وَأَنزَلۡنَا مَعَهُمُ ٱلۡكِتَٰبَ وَٱلۡمِيزَانَ﴾⟪57:25⟫ فالكتاب: الأحكام، والميزان: العدالة، ومعنى الحكمة قد تقدم أنها معرفة حقائق الأشياء وحقيقتها إنما هي لله عز وجل، وإذا استعمل في غيره، فمبلغ ذلك تقدم طاقة البشر، وهي أعم من النبوة، فكل نبي حكيم، وليس كل حكيم نبيا، وقوله: ﴿وَعَلَّمَهُۥ مِمَّا يَشَآءُۗ﴾⟪2:251⟫ إشارة إلى العلوم النبوية التي لا وصول إليها إلى بالوحي، وفي قوله تعالى:\n﴿وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ﴾⟪2:251⟫ تنبيه على فضيلة الملك، وأنه لولاه لما استتب أمر العالم، ولهذا قال الدين والملك مقترنان، وتوأمان لا يفترقان، ففي ارتفاع أحدهما ارتفاع الآخر، لأن الدين أس، والملك حارس، ومالا أس له فمهدوم، وما لا حارس له فضائع، وعلى ذلك قوله: ﴿وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّهُدِّمَتۡ صَوَٰمِعُ وَبِيَعٞ وَصَلَوَٰتٞ﴾⟪22:40⟫ الآية\nإن قيل: على أي وجه دفع الله الناس ببعضهم؟ قيل: على وجهين أحدهما: دفع ظاهر، والثاني دفع خفي، قال: فالظاهر، ما كان بالسواس الأربعة الذين هم الأنبياء، والملوك، والحكماء والوعاظ، فسلطان الأنبياء على الكافة خاصهم، وعامهم، وظاهرهم، وباطنهم، وسلطان الملوك على ظواهر الكافة دون الباطن وسلطان الحكماء على الخاصة دون العامة، وسلطان الوعاظ على بواطن العوام وأما الدفع الخفي فسلطان العقل، فالعقل يدفع عن كثير من المقابح، وهو السبب في التزام حكم السلطان الظاهر، وقوله تعالى: ﴿وَلَٰكِنَّ ٱللَّهَ ذُو فَضۡلٍ عَلَى ٱلۡعَٰلَمِينَ﴾⟪2:251⟫\nإن قيل: ما فائدة ذلك بعد قوله: آنفا ﴿إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ﴾؟\n⟦1:515⟧\nقيل: بين في الأول فضله على الناس بما خصهم به من الفضائل الإنسانية، وبين ها هنا نعمته على جميع العالمين، والحيوانات، والروحانيات، والجمادات، فإن العالمين يتناول كل ذلك، وإلى نحوه أشار بقوله: ﴿وَإِن مِّن شَيۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِهِۦ﴾⟪17:44⟫."}, {"a": [252], "v": 1, "p": 515, "ev": 1, "ep": 516, "sid": 516, "t": "قوله - عز وجل:\n﴿تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۚ وَإِنَّكَ لَمِنَ ٱلۡمُرۡسَلِينَ﴾⟪2:252⟫ الآية: (252) - سورة البقرة.\nإن قيل: ما فائدة قوله: ﴿وَإِنَّكَ لَمِنَ ٱلۡمُرۡسَلِينَ﴾⟪2:252⟫ في هذا الموضع؟ وهل خفي ذلك عليه حتى يذكره به؟ وما تعلق ذلك بما قبله؟\nقيل: يجوز أن يكون تقديره (وإنك لمن المرسلين بها)، لكن لفظة بها إيجاز، أو يجوز أن تكون الآية متقدمتين محذوفتي النتيجة على تقدير: إذا كان حال المرسلين وأممهم ما نتلوه عليك، وأنت مرسل إلى قومك كما أرسل المرسلون إلى قومهم، فلا عجب أن تجري مع قومك مجرى أمرهم مع قومهم، والإشارة بذلك إلى معنى قوله: ﴿وَكُلّٗا نَّقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآءِ ٱلرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَۚ﴾⟪11:120⟫ وقوله: ﴿فَٱصۡبِرۡ كَمَا صَبَرَ أُوْلُواْ ٱلۡعَزۡمِ مِنَ ٱلرُّسُلِ﴾⟪46:35⟫.\nإن قيل ما فائدة اقتران التلاوة بالحق؟\nقيل: قوله: بالحق في موضع الحال، كأنه قال: وهو الحق، وعلى تحمل عندي قوله: رب أحق بالحق.\n⟦1:516⟧"}, {"a": [253], "v": 1, "p": 516, "ev": 1, "ep": 520, "sid": 517, "t": "قوله - عز وجل:\n﴿تِلۡكَ ٱلرُّسُلُ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضٖۘ مِّنۡهُم مَّن كَلَّمَ ٱللَّهُۖ وَرَفَعَ بَعۡضَهُمۡ دَرَجَٰتٖۚ وَءَاتَيۡنَا عِيسَى ٱبۡنَ مَرۡيَمَ ٱلۡبَيِّنَٰتِ وَأَيَّدۡنَٰهُ بِرُوحِ ٱلۡقُدُسِۗ وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلَ ٱلَّذِينَ مِنۢ بَعۡدِهِم مِّنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ وَلَٰكِنِ ٱخۡتَلَفُواْ فَمِنۡهُم مَّنۡ ءَامَنَ وَمِنۡهُم مَّن كَفَرَۚ وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلُواْ وَلَٰكِنَّ ٱللَّهَ يَفۡعَلُ مَا يُرِيدُ﴾⟪2:253⟫\nالآية: (253) - سورة البقرة.\nإن قيل: على أي وجه تفضيل بعضهم على بعض؟\nأبتخصيص بعضهم بمنحة؟ كقولك: \" فضلت فلانا في العطاء؟ أو بالحكم والقول \"، كقولك: \" فضلت زيدا على عمرو في العلم \"؟ قيل: بالأمرين جميعا، فإن الله تعالى جعل لمن رشحه للنبوة فضائل خصه بها، ابتداء وفضائل هداه إليها ليصيبها، فما خصهم به أن جعل كل واحد في نفسه وأخلاقه معرى من عاهة تشينه، وأيده بأنواع كرامات وزيادة معاون تشرح صدره، وحدد عليه في كل وصايا تسدده، وعاتبه في أذى زلة ظهر منه، فهذا التفضيل الذي جعله ابتداء، وأما تفضيله لهم بالحكم، فعلى حسب ما يظهر من أفعالهم، فمعلوم أنه ليس حظ يونس - عليه الصلاة والسلام - حيث حذر نبينا - عليه الصلاة والسلام أن يكون مثله في الصبر بقوله:\n﴿وَلَا تَكُن كَصَاحِبِ ٱلۡحُوتِ إِذۡ نَادَىٰ وَهُوَ مَكۡظُومٞ﴾⟪68:48⟫ كحظ الذين حثه على الاقتداء بهم في قوله: ﴿فَٱصۡبِرۡ كَمَا صَبَرَ أُوْلُواْ ٱلۡعَزۡمِ مِنَ ٱلرُّسُلِ﴾⟪46:35⟫، فالتفضيل يحصل بالأمرين ، وللتفاضل بينهم قال عليه الصلاة والسلام: \" فضلت على الأنبياء بست: أوتيت جوامع الكلم، ونصرت بالرعب، وأحلت لي الغنائم، وجعلت لي الأرض مسجدا وطهورا، وختم بي النبيون، وأرسلت إلى الناس كافة \" ..\n⟦1:517⟧\nولما كانت هذه الأشياء موهبية لا مكتسبة، قال عليه الصلاة والسلام: \" أنا سيد ولد آدم ولا فخر \" تنبيها أن الفخر لا يستحق إلا بالمكسوب دون الموهوب، ونحو هذه الآية في تفضيل بعض الأنبياء على بعض قوله: ﴿وَلَقَدۡ فَضَّلۡنَا بَعۡضَ ٱلنَّبِيِّـۧنَ عَلَىٰ بَعۡضٖۖ وَءَاتَيۡنَا دَاوُۥدَ زَبُورٗا﴾⟪17:55⟫.\nوهذا حكم في الملائكة بقوله: ﴿ٱللَّهُ يَصۡطَفِي مِنَ ٱلۡمَلَٰٓئِكَةِ رُسُلٗا وَمِنَ ٱلنَّاسِۚ﴾⟪22:75⟫، وقوله: ﴿وَرَفَعَ بَعۡضَهُمۡ دَرَجَٰتٖۚ﴾⟪2:253⟫ قيل إشارة إلى النبي - صلى الله عليه وسلم - الله،\nفإن قيل: ولم لم يصرح بذكره أو بوصفه، كما فعل بموسى وعيسى؟ قيل: تقدم أن مورد كلام الله تعالى مورد خطاب الناس فيما بينهم، ولما كان المستحسن في بعض المواضع أن يذكر الممدوح المخاطب تعريضا، فيكون أبلغ من التصريح لما جرى من عادتهم أن مدح المواجهة هجاء، والثناء في الوجه قبيح، وتارة لأن الإطراء قد يدعو إلى الغفلة، وتارة لكون الممدوح بذلك المدح مستغني به عن ذكره كما قال الشاعر:\nوإني في بنى ثنائك جاهدا ..\nوقد علمت أضعاف ذاك الخلائق\nكمن قال إن الثلج أبيض بارد ..\nوأن شهاب النار أحمر حارق\nوهذا وهذا بينان كلاهما ..\nلمن هو رائي ولمن هو ذائق\nوروح القدس إشارة إلى ما خص به عيسى مما كان يحي به الموتى ملكا، أو قوة، أو اسما من أسمائه أو علما، وقد فسر بكل ذلك، وسمي جبريل - عليه السلام - روح القدس، والروح الأمين في قوله: ﴿نَزَلَ بِهِ ٱلرُّوحُ ٱلۡأَمِينُ ۝ عَلَىٰ قَلۡبِكَ﴾⟪26:193-194⟫ وفي قوله: ﴿قُلۡ نَزَّلَهُۥ رُوحُ ٱلۡقُدُسِ مِن رَّبِّكَ﴾⟪16:102⟫.\n⟦1:518⟧\nإن قيل: على أي وجه قال: ﴿وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلَ ٱلَّذِينَ مِنۢ بَعۡدِهِم﴾⟪2:253⟫ وكيف قال: ﴿وَلَٰكِنِ ٱخۡتَلَفُواْ﴾⟪2:253⟫ ولفظة ﴿لَكَانَ﴾ هي للتدارك، فما المتدارك ها هنا؟\nقيل: ذكر تعالى أنه لو شاء أن لا يقتتلوا الفعل، ولكن أراد ذلك لأنهم اختلفوا، فمنهم من آمن ومنهم من كفر، فكانت الحكمة تقتضي أن يؤمر المؤمنون بقتال الكافرين، ففي قوله: ﴿وَلَٰكِنِ ٱخۡتَلَفُواْ﴾⟪2:253⟫ حذف على سبيل الاختصار تقديره \" لكن شاء فإنهم اختلفوا، أو الاختلاف كالسبب لتلك المشيئة،\nفإن قيل: وما معنى تكرير: ﴿وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلُواْ وَلَٰكِنَّ ٱللَّهَ يَفۡعَلُ مَا يُرِيدُ﴾⟪2:253⟫؟\nقيل: أما الأول: فلأنه أمرهم بالاقتتال، لأنهم اختلفوا، وفي الثاني: ذكر أنه لو شاء لم يكن منهم اقتتال على وجه لا بعده ولا قبله، أما لأنه لم يكن يعطيهم القوة أو يميتهم قبل القتال، أو كان يمنعهم بمرض أو بسبب من الأسباب، ويجوز أن يريد بالاقتتال الأول: الاختلاف المؤدي إلى الاقتتال على طريقة ما يقال بين القوم، اقتتال: أي اختلاف يؤدي إلى ذلك، والمعنى لو شاء الله ما اختلفوا وكانوا أمة واحدة، كقوله: ﴿وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةٗ وَٰحِدَةٗ﴾ وقوله: ﴿وَلَوۡ شَآءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةٗ وَٰحِدَةٗۖ﴾⟪11:118⟫ الآية ..\nوبالاقتتال الثاني حصول المحاربة بينهم ..\nإن قيل: ما الفرق بين المشيئة والإرادة؟\nقيل: أكثر المتكلمين لم يفرقوا بينهما وإن كانتا في أصل اللغة، وفي الحقيقة مختلفتين وذلك أن المشيئة أصلها من شيء، والشيء اسم للموجود، والمشيئة قصد إلى اتخاذ الشيء، ثم يقال: شاء الله كذا أي أوجده بعد أن لم يكن موجودا، وقال بعضهم: الشيء والشاء من أصل واحد، وقلب الفعل، واستدل\n⟦1:519⟧\nعلى ذلك بقولهم: أشياء، وتأخير الهمزة فيه وإن كان أكثر أهل التصريف ينكرون ذلك، لكونها غير مصروفة، ويقولون كان فعلا كطرفاء، فقلب، فصار على أمعاء، ومن اعتبر هذا الاعتبار بقول الواو والياء، لاعتبار ما عناهما، فكل واحدة منهما يعرض الانقلاب إلى الأخرى على حسب ما يقتضي خفة اللفظ وثقله أو التفريق بين معنيين، وأما الإرادة، فمصدر أراد، أي طلب، وأصله أن يتعدى إلى مفعولين، لكن اقتصر على أحدهما في التعارف، وفي الأصل لا يقال إلا لأن تطلب ممن يصح منه الطلب كالإطلاب، فإن بدل منه هذا الاعتبار في التعارف، وصار لطلب الشيء والحكم بأنه ينبغي أن يفعل أولا يفعل، وإذا استعمل في الله، فهو للحكم دون الطلب، إذ هو تعالى منزه عن الوصف بذلك.\n⟦1:520⟧"}, {"a": [254], "v": 1, "p": 520, "ev": 1, "ep": 523, "sid": 521, "t": "قوله - عز وجل:\n﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِمَّا رَزَقۡنَٰكُم مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا بَيۡعٞ فِيهِ وَلَا خُلَّةٞ وَلَا شَفَٰعَةٞۗ وَٱلۡكَٰفِرُونَ هُمُ ٱلظَّٰلِمُونَ﴾⟪2:254⟫ الآية: (254) - سورة البقرة.\nقد تقدم الكلام في معنى البيع والشراء، وإن كل واحد منهما يوضع موضع الآخر، ومبايعة الولاية من ذلك، والبيعة يجوز أنها سميت بذلك نظرا إلى نحو معنى قوله: ﴿إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ﴾⟪9:111⟫ الآية، كأنه الحالة التي يتبع الإنسان نفسه فيها من الله فسمي المكان الذي يحصل ذلك فيه بها، والخلل انفراج الشيئين، يقال: خللته: أي أصبت خلله، فاستعير منه الخليل، إما لتخلل كل واحد منهما قلب الآخر كما قيل: الحبيب لوصول كل واحد منهما إلى حبة قلب الآخر ..\nقال الشاعر:\nقد تخللت مسلك الروح مني\n.....\nوبذا سمي الخليل خليلا\nأو لأنه تخلل أحوال الآخر، وعرف سرائره، ولهذا قيل أطلعته على عجزي، وتحرى فيهما عرقين في البطن، وبهذا النظر قال الشاعر:\nلا تكتمن ذاك الطبيبا\n....\nولا الصديق سرك المكتوما\nأو لاعتبار افتقار كل واحد منهما إلى الآخر، وبهذا النظر قيل: الصديق للإنسان ضروري، وقوله تعالى: ﴿وَٱتَّخَذَ ٱللَّهُ إِبۡرَٰهِيمَ خَلِيلٗا﴾⟪4:125⟫ على الاعتبار الأخير، وهو افتقاره إلى الله - عز وجل - في كل حال، كما أخبر عن موسى بقوله: ﴿رَبِّ إِنِّي لِمَآ أَنزَلۡتَ إِلَيَّ مِنۡ خَيۡرٖ فَقِيرٞ﴾⟪28:24⟫ وبهذا الفقر أشرف غنى،\n⟦1:521⟧\nبل أشرف فضيلة يكتسبها الإنسان، ولهذا قيل عليه الصلاة والسلام: \" اللهم اغنني بالافتقار إليك، ولا تفقرني بالاستغناء عنك \".\nحث الله تعالى المؤمنين على ما رزقهم من النعمى النفسية والبدنية والخارجة، وإن كان الأظهر في التعارف وإنفاق المال، لكن قد يراد به بذلك النفس والبدن في مجاهدة العدو والهوى وسائر العبادات كما تقدم في قوله: ﴿مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا﴾ ولما كانت الدنيا دار اكتساب وابتلاء، والآخرة دار ثواب وجزاء، بين أن لا سبيل للإنسان إلى تحصيل ما ينتفع به في الآخرة ابتداء، وذكر هذه الثلاثة لأنها أسباب اجتلاب المنافع المقصود إليها أحدها المعاوضة، وأعظمها المبايعة، والثاني: ما يناله بالمودة، وهو المسمى الصلات والهدايا، والثالث: ما يصل إليه بمعاونة الغير، وذلك هو الشفاعة فبين تعالى أن من لم يكتسب في الدنيا ما ينتفع به في الآخرة لم يحصل له ذلك في الآخرة، وعلى هذا قال: ﴿وَٱتَّقُواْ يَوۡمٗا لَّا تَجۡزِي نَفۡسٌ عَن نَّفۡسٖ شَيۡـٔٗا وَلَا يُقۡبَلُ مِنۡهَا شَفَٰعَةٞ﴾⟪2:48⟫ وقوله ﴿مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا بَيۡعٞ فِيهِ وَلَا خُلَّةٞ﴾⟪2:254⟫ ﴿وَلَا خِلَٰلٌ﴾⟪14:31⟫ وفي الآية قول آخر وهو أن الناس في عبادة الله تعالى على ثلاثة أضرب، سابق حصل له منزلة الخلة، والمحبة المقصود إليها بنحو قوله: ﴿إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلۡمُتَطَهِّرِينَ﴾⟪2:222⟫ وغيره من الآيات التي تجري مجراها، وهو الذي يعبد الله لا لرغبته، ولا رهبة، ولا لطلب مثوبة، ومقتصد حصل له منزلة المبايعة المذكورة في قوله: ﴿إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ﴾⟪9:111⟫ وفي قول النبي - صلى الله عليه وسلم -:\n⟦1:522⟧\n\" الناس غاديان: مبتاع نفسه فمعتقها، وبائع نفسه فموبقها \" وهو الذي يعبد الله خوف عقاب ورجاء ثواب، وظالم لنفسه، وهو المؤمن المقصر في استفادة المنزلتين المتقدمتين المتواكل في علمه وعمله المذكور في قوله: ﴿وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُوْلَٰٓئِكَ مَعَ ٱلَّذِينَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِم﴾⟪4:69⟫ وهو المستحق للشفاعة المذكور في قوله - صلى الله عليه وسلم -: \" شفاعتي لأهل الكبائر من أمتي \" فبين تعالى أن من لم يحصل له إحدى هذه المنازل الثلاث فلا سبيل له إلى اكتسابها في الآخرة، وقوله: ﴿وَٱلۡكَٰفِرُونَ هُمُ ٱلظَّٰلِمُونَ﴾⟪2:254⟫ لما كانت العدالة بالقول المجمل ثلاث:\nعدالة بين الإنسان ونفسه، وعدالة بينه وبين الناس، وعدالة بينه وبين الله تعالى، كذلك للظلم ثلاثة في مقابلتها وأعظم العدالة ما بين الإنسان وبين الله وهو الإيمان، وأعظم الظلم ما في مقابلته وهو الكفر، فلذلك قال: ﴿وَٱلۡكَٰفِرُونَ هُمُ ٱلظَّٰلِمُونَ﴾⟪2:254⟫ أي هم المستحقون إطلاق هذا الوصف عليهم بلا مثوبة ..\nإن قيل: كيف تعلق قوله: ﴿وَٱلۡكَٰفِرُونَ هُمُ ٱلظَّٰلِمُونَ﴾⟪2:254⟫ بما قبله؟\nقيل: لما نفى أن يكون للكفار شيء مما ذكره في الآخرة، بين أن ذلك ليس بظلم منه لهم، لكن هم الظالمون إذ هم الذين خسروا أنفسهم ..\nإن قيل:\nكيف نظم هذه الآية مع التي قبلها؟\nقيل: لما بين في الأولى أن منهم من آمن ومنهم من كفر، خوف المؤمنين أن يتحروا ما يخشى منه\n⟦1:523⟧\nاجتلاب الكفر، وهو ترك الإنفاق على ما تقدم قوله .."}, {"a": [255], "v": 1, "p": 523, "ev": 1, "ep": 529, "sid": 524, "t": "قوله - عز وجل:\n﴿ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا يَـُٔودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ﴾⟪2:255⟫ الآية: (255) - سورة البقرة.\nقد تقدم أنواع الحياة، وأن أشرفها الحياة الأبدية في الآخرة، وإذا وصف الباري - عز وجل - بها، فمعناه الدائم الذي لم يزل ولا يزال، ولا يصح عليه الموت بوجه، والتحية بذل الحياة فإذا قيل.\n\" حياك الله \"، فمعناه: خولك الحياة، وكذا إذا قيل: \" حياك فلان \" غير أن الأول إعطاء بالفعل، والثاني بالقول وكذلك التسليم إعطاء السلامة على أحد الوجهين، والقيوم فيعول، وقال: فيعال، وكذلك واوه لأن الواو والياء إذا اجتمعا والأولى ساكنة، قبلت الواو ياء، وعلى ذلك \" ديار \" ولو كان فعلها لقيل قوام، ودوار \" يقال قام كذا \" أي دام، وقام بكذا، أي حفظه، والقيوم في وصفه تعالى هو الدائم الحافظ للعالم وجواهره وأعراضه، والقصد بمعناه إلى قوله: ﴿إِنَّ ٱللَّهَ يُمۡسِكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ أَن تَزُولَاۚ﴾⟪35:41⟫ ومن قال: القيوم بالشيء: العالم به، فصحيح أيضا، لأن حفظ الشيء يقتضي المعرفة به، ولهذا قيل للمعرفة الحفظ، ولضدها النسيان، وأصل النسيان الترك، والأخذ يعبر به عن الاستيلاء على الشيء والقهر يقال: أخذته الحمى، وفلان مأخوذ ومقهور، والسنة: عبارة عن الفتور والغفلة، والنوم يفسر على أوجه كلها صحيح، الأول: أنه استرخاء أعصاب الدماغ برطوبة البخار الصاعد إليه، وذلك بالنظر الطبي، والثاني: أن يتوفى الله النفس من غير موت، وهو الذي قال: ﴿ٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا وَٱلَّتِي لَمۡ تَمُتۡ فِي مَنَامِهَاۖ﴾⟪39:42⟫ وقيل: ترك الروح: استعمال الحواس من خارج إجماما لها، وسئل بعض\n⟦1:524⟧\nالحكماء عن الفرق بين النوم والموت، فقال : الموت نوم ثقيل، والنوم موت خفيف، ولما كان النوم يقتضي السكون، قيل لمن يسكن إلى إنسان أو شيء استنام إليه، وإلى مقتضاه أشار بشار بقوله:\nإذا أيقظتك حروب العدا\n....\nفنبه لها عمرا ثم نم\n﴿مَا بَيۡنَ أَيۡدِيهِمۡ﴾⟪2:255⟫ قيل: الماضي، ﴿وَمَا خَلۡفَهُمۡۖ﴾⟪2:255⟫ المستقبل، وقيل على العكس من ذلك، وهذا الاختلاف لاختلاف تصور ما اعتبر به الخلف والقدام، ولهذا يقال: خلفت كذا لما قضيته، وخلفي كذا لما لم تفعله بعد، وعلى ذلك قيل: وراءهما: الخلف والقدام، وقيل: ﴿مَا بَيۡنَ أَيۡدِيهِمۡ﴾⟪2:255⟫: الدنيا، ﴿وَمَا خَلۡفَهُمۡۖ﴾⟪2:255⟫ الآخرة، وقيل بالعكس من ذلك، وقيل: ﴿مَا بَيۡنَ أَيۡدِيهِمۡ﴾⟪2:255⟫: المحسوس، ﴿وَمَا خَلۡفَهُمۡۖ﴾⟪2:255⟫ المعقول، وقيل: ﴿مَا بَيۡنَ أَيۡدِيهِمۡ﴾⟪2:255⟫ المحسوس والمعقول، ﴿وَمَا خَلۡفَهُمۡۖ﴾⟪2:255⟫ الغيوب التي لا سبيل للإنسان إلى معرفتها، والكرسي في تعارف العامة اسم لما يقعد عليه، وهو في الأصل منسوب إلى الكرسي أي الملبد، والكراسة للمتكرسة من الأوراق، والكروس، للمتراكب بعض أجزاء رأسه على بعض لكبره، والكرياس: الكنيف المكرس بالفناء إلى السطح، وروي ابن عباس: أن الكرسي: العلم، وليس ذلك بتعبد من حيث الاشتقاق نسبة إلى الأوراق التي تثبت فيها العلوم، كقولك: كراسي، وقيل: كرسيه: أصل ملكه، وكراسي القوم معتمدهم، وأنشد:\nتخف بهم بيض الوجوه وعصبة\n....\nكراسي بالأحداث حين تثوب\n⟦1:525⟧\nوقيل: كرسيه: مملكته، وقيل: اسم الفلك المحيط بالأفلاك، ويشهد لذلك ما روي أبو ذر عن النبي - صلى الله عليه وسلم - قال: (ما السماوات السبع في جنب الكرسي إلا كحلقة ملقاة بأرض فلاة، وفضل العرش على الكرسي كفضل تلك الفلاة على تلك الحلقة)، وقال عليه الصلاة والسلام: (الكرسي لؤلؤة طولها لا يعلمها العالمون، وأعظم من سبع سماوات وسبع أرضين، وهو من خير الجوهر) وعن ابن عباس أن رجلا أتاه، فسأله ثلاث مرات عن هذه الآية، وعن قول الله: «الذي خلق سبع سماوات سموات» فلم يرد عليه شيئا فلما خف عنه الناس، قال له الرجل: ما منعك أن تجيبني؟\nفقال: \" وما يؤمنك إن أخبرتك أن تكفر؟ سماء تحت أرض، وأرض فوق سماء، مطويات بعضها فوق بعض، يدور الأمر بينهن \"، والخبر الأول يدل أن جوهر الكرسي والسماء أشرف مما عرفناه، والخبر الأخير يدل على أن الفلك كروي، وما روى أن الكرسي موضع القدمين، وأن له أطيطا كأطيط الرحل الحديد فصحيح، ومعناه لا يخفي على من عرف الله عز وجل - وعرف الأجرام السماوية\n⟦1:526⟧\nومجازات اللغة، ونظر من المعنى إلى اللفظ لا من اللفظ إلى المعنى، ومن لم يعرف ذلك فحقه أن يسلم اللفظ للرواية دون تكذيب الآية، ويترك الخوض فيما لا يعلم إتباعا لقوله تعالى: ﴿وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ﴾ وليس في إثبات الكرسي له إثبات كونه جسما محدودا، كما أنه ليس في إثبات البيت له إثبات كونه ساكنة وليس في نسبة القدم إليه إثبات جارحة، كما أنه ليس في قوله - عليه الصلاة والسلام في وصف أولياء الله عز وجر - \" أكون سمعه الذي يسمع به، وعينه التي يبصر بها، ويده التي يبطش بها \" إثبات جارحة، و \" لا يؤوده \" - لا يثقله أصله من الأول العوج، ولما جرت العادة أن متحمل الثقل يعوج في الممر استعير (أده) كذا للثقل، وقوله: ﴿لَآ إِلَٰهَ إِلَّا هُوَ﴾⟪2:255⟫ معناه: الله هو الذي يحق له العبادة لا غير، وقيل: الله الذي ولهت الأشياء كلها له، وذاك أنه ما من إنسان مؤمن وكافر، بل ما من حيوان إلا إذا نابته نابية شديدة اعتمد عليه، ووله إليه، ولهذا قيل: \" الله محبوب الأشياء كلها إما بطبعها، وإما بقصدها، وقوله: ﴿لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ﴾⟪2:255⟫ تأكيد لما اقتضاه الحي القيوم - تنبيها أنه وإن شارك الأحياء في الاسم، فقد فارقها في الحقيقة، إذ كان سائر الأحياء لا ينفك من غفلة ونوم ..\nإن قيل: كيف خص بملكه ما في السماوات والأرض، وذلك يوهم أن ليس له السماوات والأرض؟\nقيل: لم يرد بقوله ﴿فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ﴾ معنى الشيء في الوعاء وفي المكان، وإنما يريد ما تركب منه السماوات والأرض من الجواهر والصور والأعراض والصنع، فصار ذلك من وجه أبلغ من قولك ﴿ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ﴾، إذ قد يحصل للمالك ما ليس بمصنوعه، على أنا لو نظرنا من حيث\n⟦1:527⟧\nنظرت، لم يكن يقتضي ذلك ما ذكر، لأنه لما قصد تعالى تعريفنا قدرته، ذكر لنا ما يمكننا إدراكه لنستدل به على ما لا نعرفه والإحاطة بالسماوات والأرض لا سبيل لنا إليها، وقد تقدم آنفا حقيقة الشفاعة، وذكر مستحقيها، وأن ذلك لمن كان منه تقصير في العلم والعمل، غير أنه لم يخرج عن خطر الشريعة وعن الائتمار لرسل الله وخلفائهم من أهل العلم في الاعتماد الوصول وكون ما جاءوا به حقا، وهم الذين أذن تعالى في الشفاعة فيهم، وعناهم بقوله:\n﴿وَلَا يَشۡفَعُونَ إِلَّا لِمَنِ ٱرۡتَضَىٰ﴾⟪21:28⟫، وقوله: ﴿وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ﴾⟪2:255⟫ نفى تعالى عنا الإحاطة بشيء من علمه، وكيف يمكن لنا ذلك، وقد علم أن المحيط بنا علما، كما قال - عز وجل: ﴿قَدۡ أَحَاطَ بِكُلِّ شَيۡءٍ عِلۡمَۢا﴾⟪65:12⟫ ومن المحال أن يكون المحيط بكل شيء يحيط به شيء، وقوله: ﴿مِّنۡ عِلۡمِهِۦٓ﴾⟪2:255⟫ على وجهين: أحدهما مما يعلمه، وهو ويكون العلم مضافا إلى الفاعل، والثاني: أن يعلمه الخلق ليكون مضافا إلى المفعول به، أي لا يحيطون أي يعلموه تنبيها أن معرفته على الحقيقة متعذرة، بل لا سبيل إليها، وإنما غايتها أن يعرف الموجودات، فيتحقق أن ليس إياها، ولا شيئا منها، ولا شبيها بها،\n⟦1:528⟧\nبل هو سبب وجود جميعها، وأنه يصح ارتفاع كل ما عداه مع بقائه تعالى، وبهذا النظر قال أبو بكر - رضي الله عنه - \" سبحان من لم يجعل لخلقه سبيلا إلى معرفته إلا بالعجز عن معرفته \"، وقال بعض الأولياء: \" غاية معرفة الله أن تعلم أنه يعرفك لا أنك تعرفه \"، ولهذا قيل: ﴿هُوَ ٱلۡأَوَّلُ وَٱلۡأٓخِرُ وَٱلظَّٰهِرُ وَٱلۡبَاطِنُۖ﴾⟪57:3⟫ وقال أمير المؤمنين:\n\" تجلى لعباده في القرآن من غير أن يروه، وأراهم نفسه من غير أن يتجلى لهم \"، وقوله: ﴿إِلَّا بِمَا شَآءَۚ﴾⟪2:255⟫ أي: إلا بما شاء أن يقفهم عليه من القليل الذي قال: ﴿وَمَآ أُوتِيتُم مِّنَ ٱلۡعِلۡمِ إِلَّا قَلِيلٗا﴾⟪17:85⟫ ثم أكد بما فيه عليه بقوله: ﴿وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ﴾⟪2:255⟫ بقوله: ﴿وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ﴾⟪2:255⟫ أي إذا كان علمه ومملكته وقدرته محيطة بهذه الأشياء والإنسان بعض هذه الأشياء، فكيف تصح إحاطته بمن هو محيط بهذه الأشياء وهو يعجز عن الإحاطة بها، والعلي هو القاهر فوق عباده، وقيل: العلي عن النظير، وقيل: القادر على حفظه، وقيل: القائم به، وكل ذلك راجع إلى التنبيه على قدرته وسلطانه وأن ما عداه مستحقر بالإضافة إليه.\n⟦1:529⟧"}, {"a": [256], "v": 1, "p": 529, "ev": 1, "ep": 532, "sid": 530, "t": "قوله - عز وجل:\n﴿لَآ إِكۡرَاهَ فِي ٱلدِّينِۖ قَد تَّبَيَّنَ ٱلرُّشۡدُ مِنَ ٱلۡغَيِّۚ فَمَن يَكۡفُرۡ بِٱلطَّٰغُوتِ وَيُؤۡمِنۢ بِٱللَّهِ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰ لَا ٱنفِصَامَ لَهَاۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ﴾⟪2:256⟫ الآية: (256) - سورة البقرة.\nالغي كالجهل، إلا أن الجهل يقال اعتبارا بالاعتقاد والغي اعتبارا بالأفعال، ولهذا يقال: الجهل بالعلم، والغي بالرشد، ويقال لمن أصاب رشد، ولمن أخطأ غوى، وعلى هذا قال الشاعر:\nومن يغو لا يعدم على الغي لائما\nوالطاغوت وزنه (فعلوت)، نحو جبروت وأصله طغووت، لكن قلب لام الفعل نحو: صاعقة وصاعقة، ثم قلب الواو ألفا لتحركه وانفتاح ما قبله، ويسمى كل ما يصرف عن الله عز وجل - طاغوتا وشيطانا كان أو إنسانا، ولهذا روي عن عمر ومجاهد وقتادة أنه الشيطان، وعن ابن جبير أنه الكاهن، وعن أبي العالية أنه الساحر، وعن غيرهم أنه صنم، وقيل: هو المارد من الناس والجن، وكلهم صارفون للإنسان عن طريق الحق، وقد تقدم أن النهي عن أتباع الطاغوت والشيطان، وإبليس والهوى\n⟦1:530⟧\nوالدنيا يجري مجرى واحدا في أن المقصد به النهي عما لا يرضاه الله، وقوله:\n﴿فَمَن يَكۡفُرۡ بِٱلطَّٰغُوتِ﴾⟪2:256⟫، كقوله: ﴿وَأَمَّا مَنۡ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفۡسَ عَنِ ٱلۡهَوَىٰ﴾⟪79:40⟫ وعلى ذلك حث بقوله: ﴿وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَيُضِلَّكَ﴾⟪38:26⟫ وقوله: ﴿أَن لَّا تَعۡبُدُواْ ٱلشَّيۡطَٰنَۖ﴾⟪36:60⟫ والكره يقال على ضربين: أحدهما أن يكون مفسرا من خارج، وذلك على أحد الأوجه الثلاثة، إما بأن يهدد بالضرب أو يضرب حتى يفعل، وإما أن تؤخذ يده فيفعل بها، فيكون في هذا كلالة، وإما أن يدعوه من يزينه في عينه، والثاني: ما يكون مفسرا من داخل، وذلك إما بخوف يستشعره، وإما بهوى يغلبه، وقد روعي كل ذلك في تفسير الآية، فقيل فيه أوجه:\nالأول: إن ذلك حث على أن لا يحمل الإنسان على الدين بالقسر، بل يعرض عليه الإسلام عرضا ويعرف فضله، فإن قبل: وإلا ترك؟ قيل: وهذا حكم كان في ابتداء الإسلام، ثم نسخ بسورة براءة، وذلك عن السدي، وابن زيد، والثاني: نحو ذلك، غير أنه خص بمن قبل منهم الجزية دون مشركي العرب، وذلك عن الحسن، وقتادة، والضحاك، وعلى هذين معناه: أمن، والثالث: أن قوله تعالى: ﴿لَآ إِكۡرَاهَ﴾⟪2:256⟫ لا اعتبار بالإكراه في الأحكام الدنيوية، فالمكره على الإسلام، وغير المكره سيان بعد أن يلتزما ..\n⟦1:531⟧\nوالرابع: لا حكم للكفر لمن أكره على الكفر، والدين يكون لغير الحق على هذا نحو ﴿إِلَّا مَنۡ أُكۡرِهَ وَقَلۡبُهُۥ مُطۡمَئِنُّۢ بِٱلۡإِيمَٰنِ﴾⟪16:106⟫.\nالخامس: لا اعتداد في الآخرة بما يفعل الإنسان في الدنيا من الطاعة كرها، وكرها، فإن الله يعتبر السرائر ولا يرضى إلا الإخلاص، ولهذا قال عليه الصلاة والسلام:\n\" الأعمال بالنيات \" وقال: \" أخلص يكفك القليل من العمل \".\nالسادس: ليس يحمل الإنسان على أمر مكروه في الحقيقة بما يكلفهم الله، بل يحملون على نعيم الأبد، ولهذا قال عليه الصلاة والسلام: \" عجب ربكم من قوم يقادون إلى الجنة بالسلاسل \".\nالسابع: أن الله تعالى ليس بمكره على الجزاء، بل يفعل ما يشاء بمن يشاء على ما يشاء، والاستمساك طلبك إلى الغير ليمسك كالاستحفاظ والاستنصار، و ﴿بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰ﴾⟪2:256⟫ مستعارة للعبد المركون إليه كالحبل في نحو:\nأخذت بحبل من حبال محمد\n....\nأمنت به من طارق الحدثان\n⟦1:532⟧\nونحو:\nقوم إذا عقدوا عقدا لجارهم\n....\nشدوا العناج وشدوا فوقه الكربا\nفقول من قال: العروة الوثقى الإسلام، وقول من قال: \" لا إله إلا الله، وقول من قال: الثواب: الجنة، فنظرات منهم إلى مبتدى الدين ومنتهاه، وكله صحيح."}, {"a": [257], "v": 1, "p": 532, "ev": 1, "ep": 536, "sid": 533, "t": "قوله - عز وجل:\n﴿ٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ يُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۖ وَٱلَّذِينَ كَفَرُوٓاْ أَوۡلِيَآؤُهُمُ ٱلطَّٰغُوتُ يُخۡرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِۗ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ﴾⟪2:257⟫ الآية - (257) - سورة البقرة\nالولي: كون الشيء بجنب الآخر، ويعتبر ذلك تارة بالمكان، فيقال له الولاية وتارة بالنصر فيقال له الولاء والموالاة، لكن الولاء على ضربين باعتبار نسبة الأعلى إلى الأسفل، وضرب باعتبار نسبة الأسفل إلى الأعلى، ولهذا يقال للخادم والمخدوم مولى، وولي، لأن كل واحد منهما يوالي الآخر الخادم بالطاعة والنصيحة، والمخدوم بالإشفاق، والكناية، وقال: أهل اللغة: المولى المالك، والمملوك والمعتق والمعتق والناصر والمنصور وابن العم والحليف والجار والقيم، وأخذوا في كل ذلك المتطابقين، لكون كل واحد مهما مواليا للآخر بوجه ..\n⟦1:533⟧\nوالنور: عبارة عن العلم والإيمان والظلمة عن ضدهما، ووجه ذلك أنه لما كان للإنسان نظرات بنظر وتبصر، ويرى بهما البصر الحاس في الرأس والبصيرة في القلب، فكما أن البصر لا يستغنى في إدراك ما يدركه من المعقولات عن نور يمده وهو نور التوفيق والإيمان، ويقال لفقد البصرين عمى، ولفقد النورين ظلمة، وأعظمهما ضررا فقد البصيرة ونور العقل، ولهذا قال تعالى:\n﴿فَإِنَّهَا لَا تَعۡمَى ٱلۡأَبۡصَٰرُ وَلَٰكِن تَعۡمَى ٱلۡقُلُوبُ ٱلَّتِي فِي ٱلصُّدُورِ﴾⟪22:46⟫ فلم يعد فقد البصر عمى.\nبالإضافة إلى فقد البصيرة، وقوله: ﴿خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَۖ﴾⟪6:1⟫ وقوله: ﴿وَيَجۡعَل لَّكُمۡ نُورٗا تَمۡشُونَ بِهِۦ﴾⟪57:28⟫ وقوله: ﴿مَن يُنَجِّيكُم مِّن ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ﴾⟪6:63⟫ يعني بذلك كلا النورين والظلمتين،\nإن قيل: وهل هذا النور موهبة أو مكتسب؟\nقيل: لا شك في كونه موهبة، لقوله تعالى: ﴿وَمَن لَّمۡ يَجۡعَلِ ٱللَّهُ لَهُۥ نُورٗا فَمَا لَهُۥ مِن نُّورٍ﴾⟪24:40⟫ لكن فيه للاكتساب حظ، فإن ابتداء ما يحصل ذلك للإنسان كشررة، متى لم ترع همدت، وإذا روعيت زادت، كما قال: ﴿وَٱلَّذِينَ ٱهۡتَدَوۡاْ زَادَهُمۡ هُدٗى﴾⟪47:17⟫ بين تعالى إن الله عز وجل - يوالي المؤمنين بأن يوفقهم ويهديهم، وهم يوالونه بأن يشكروه ويعبدوه، كما قال تعالى: ﴿يُحِبُّهُمۡ وَيُحِبُّونَهُۥٓ﴾⟪5:54⟫ فهو يخرجهم من الجهل والكفر إلى العلم والإيمان والثواب والكافرون، يواليهم الشيطان في إخراجهم إلى أضداد ذلك\nإن قيل: لم قال: أولياؤهم وما يفعل بهم الطاغوت هو بالمعاداة أشبه منه بالموالاة؟\nقيل: لعمري إن ذلك نهاية المعاداة وتسميته بالموالاة أولى لمقابلة اللفظ، وثانيا: لتحريهم ما يقع بوفاقه، وميلهم إلى حزبه، فجعله موالاهم في اللفظ لا في الحقيقة، ألا ترى أنه قال: ﴿أَلَمۡ أَعۡهَدۡ إِلَيۡكُمۡ يَٰبَنِيٓ ءَادَمَ أَن لَّا تَعۡبُدُواْ ٱلشَّيۡطَٰنَۖ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ﴾⟪36:60⟫⟦1:534⟧ فسماه عدوا، وعلى حد جعله أوليائهم جعلهم حزبه في قوله: ﴿أُوْلَٰٓئِكَ حِزۡبُ ٱلشَّيۡطَٰنِۚ﴾⟪58:19⟫ وقال للمؤمنين: ﴿إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ﴾⟪5:55⟫.\nإن قيل: فكيف قال ها هنا: ﴿أَوۡلِيَآؤُهُمُ ٱلطَّٰغُوتُ﴾⟪2:257⟫ وقال في آخر ﴿ذَٰلِكَ بِأَنَّ ٱللَّهَ مَوۡلَى ٱلَّذِينَ ءَامَنُواْ وَأَنَّ ٱلۡكَٰفِرِينَ لَا مَوۡلَىٰ لَهُمۡ﴾⟪47:11⟫.\nقيل: إن من وليه الشيطان، فلا ولي له، ولا فرق بين أن يقال: وليه من نصره، وبين أن يقال: لا ولي له، وقول من قال: الله ولي المؤمنين بتوفيقه وعصمته، ومن قال بإقامة البرهان لهم، ومن قال بنصرته على عدوهم، وإظهار دينهم على دين مخالفيهم، من قال بثوابهم، فكله صحيح ومراد، لأن ذلك متلازم، وإنما اختلفت العبارات عليهم بحسب النظرات ونحو ذلك في استعمال النور والظلمة في العلم والجهل والإيمان والكفر ..\nقوله: ﴿وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَآ أَنۡ أَخۡرِجۡ قَوۡمَكَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ﴾⟪14:5⟫ الآية.\nإن قيل: كيف؟ قال ﴿يُخۡرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِۗ﴾⟪2:257⟫ وقد قلت: النور: العلم والإيمان، والكفار لم يكونوا في هذا النور، والإخراج عن الشيء يعد لكون فيه، قيل: إن الله تعالى خلق الإنسان على فطرة، ركز فيه العلم والإيمان بالقوة، وهو المعنى بقوله: ﴿فِطۡرَتَ ٱللَّهِ﴾⟪30:30⟫، و (صبغة الله)، وقول النبي- عليه الصلاة والسلام: \" كل مولود يولد على الفطرة \"، والإنسان متى أهلك نفسه وأفسدها بالهوى والتدليس بالجهالات، فقد أخرج من النور إلا الظلمة، وقال الحسن إخراجه إياهم منعهم من الدخول فيه كقوله:\n⟦1:535⟧\n﴿لَمَّآ ءَامَنُواْ كَشَفۡنَا عَنۡهُمۡ﴾⟪10:98⟫ فجعل صيانتهم من العذاب كشفنا عنهم، وروي عن مجاهد أن ذلك في قوم ارتدوا عن الإسلام، وقيل إن ذلك نزل في قوم كفروا بعيسى ثم آمنوا بمحمد- عليهما الصلاة والسلام- فأخرجهم الله من الظلمات إلى النور، وقوم آمنوا بعيسى- عليه الصلاة والسلام-، ثم كفروا بمحمد- عليه الصلاة والسلام-، فأخرجهم الطاغوت من النور إلى الظلمة ...\nإن قيل: لم قال: يخرجونهم بلفظ الجمع؟\nقيل: قد قال بعضهم: الطاغوت يقع على الواحد والجمع كالفلك، ووجه ذلك من حيث المعنى أن الطاغوت إشارة إلى المضلات من الشيطان والهوى وسائر ما يضل، وقد قال بعض الحكماء ما هو كالتفسير، لذلك إنه متى يخالف العقل والهوى شيئا ما، أعنى: مؤلما- جميلا وملذا فضيحا، يبادر الملك إلى نصرة العقل، فيصير من حزبه، والشيطان إلى نصرة الهوى، فيصير من جنده وإن استشار صالحا من عباد الله، أشار عليه بمقتضى العقل، وإن استشار شريرا أشار عليه بمقتضى الهوى، ولذلك قال تعالى: ﴿وَكَذَٰلِكَ جَعَلۡنَا لِكُلِّ نَبِيٍّ عَدُوّٗا شَيَٰطِينَ ٱلۡإِنسِ وَٱلۡجِنِّ يُوحِي بَعۡضُهُمۡ إِلَىٰ بَعۡضٖ زُخۡرُفَ ٱلۡقَوۡلِ غُرُورٗاۚ﴾⟪6:112⟫ وقوله تعالى: ﴿وَمَن يَعۡشُ عَن ذِكۡرِ ٱلرَّحۡمَٰنِ نُقَيِّضۡ لَهُۥ شَيۡطَٰنٗا فَهُوَ لَهُۥ قَرِينٞ﴾⟪43:36⟫، وقوله تعالى: ﴿وَمَن يَتَّبِعۡ خُطُوَٰتِ ٱلشَّيۡطَٰنِ فَإِنَّهُۥ يَأۡمُرُ بِٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۚ﴾⟪24:21⟫\n⟦1:536⟧\nإن قيل: كيف نظم هذه الآية مع ما قبلها؟\nقيل: لما قرر عظمته بالآية المتقدمة، بين في هذه أن الذي له العظمة هو مولى المؤمنين تشريفا لهم، وتعظيمه لمكانتهم، وأن الشيطان مولى الكافرين تدليلا لهم، فقد قالت العرب:\n\" أشرف الموالي لي أشرفهم سيدا، أكرم السائلين أكرمهم مسؤولا \".\nوعلى هذا قال الشاعر:\nيضع الزيارة حيث لا يزري بنا ...\nشرف المزور ولا بحسب الزور"}, {"a": [258], "v": 1, "p": 536, "ev": 1, "ep": 540, "sid": 537, "t": "قوله- عز وجل:\n«ألم تر إلى الذي حاج إبراهيم في ربه أن آتاه الله الملك إذ قال إبراهيم ربي الذي يحيي ويميت قال أنا أحيي وأميت قال إبراهيم فإن الله يأتي بالشمس من المشرق فأت بها من المغرب فبهت الذي كفر والله لا يهدي القوم الظالمين»\nالآية: (258) - سورة البقرة.\nالمحاجة: المقاومة في إظهار الحجة، أي محجة الرشد، والشمس اشتق عنها شمس فلان إذا نفر تشبيها بالشمس التي لا يمكن أن يقبض عليها، وعلى ذلك قوله:\nكالشمس ضوؤها قريب ولكن في تناولها بعد وقيل: شمس إذا عادى ..\nوذاك أن حقيقة المعاداة تنافر طبع المتعاديين بعضلها من بعض من عداه إذا تجاوزه، والشمسة في القلادة تشبيها في الحسن والهيئة، والبهت أن تفعل بالإنسان ما يحيره، وسمي الكذب المستقبل به الإنسان بهتانا، لتحير صاحبه فيه ..\nوالذي حاج إبراهيم في ربه، قيل كان نمرود بن كنعان، وكان قد ملك الدنيا، ويقال: إنه ما\n⟦1:537⟧\nملكها إلا أربعة مؤمنان: وهما سليمان، وذو القرنين، وكافران: نمرود وشداد ..\nإن قيل: ما الذي ادعى هذا الكافر؟\nادعى نفي الخالق؟ أم ادعى لنفسه الربوبية؟ أم الأمرين؟ فإن ادعى الربوبية، فعلى أي وجه ادعى، فبعيد أن يزعم من وجد بعد أن لم يكن أنه موجد الخلائق ...\nقيل: قد ذكر المخلصون في ذلك وجهين، أحدهما: أن هذا الكافر نمرود، وكان الناس حينئذ يعظمون ملكهم حتى كانوا يسمونه الرب والإله، ولهذا قيل: (الله رب الأرباب وإله الآلهة)، وكانوا يدعون له أفعالا ألاهية تقصر قدر البشر عنها، وقد حكى الفرس عن ملوكهم شيئا كبيرا من ذلك كما ادعوا لكن خسرو أنه ألجأة عدو له إلى سفح جبل، فحملته الملائكة، وأن شابور لما حارب التنين، فأظلم عليه الدنيا، أنزل عليه نارا، فصارت على عرف فرسه، فاستضاء بها حتى قتل التقين، وكان نمرود لما طغى سام الناس أن يعبدوه عبادتهم لله، إذ هو بزعمهم سايسهم، وملكهم، وربهم، وإلأههم، فهذاك أحد الوجهين، والثاني: أنه كان يذهب مذهب من يقول بالحلول، أن الباري- تعالي عن ذلك- يحل في أشخاص الأئمة حسب ما ادعى بعض المتنصرة وبعض المتشيعه الملحدة، وكان نمرو يدعي الربوبية على أحد هذين الوجهين، لا أنه ينكر رب العزة ...\n⟦1:538⟧\nإن قيل: ما الذي حاج إبراهيم؟\nفإن المحكي عنه ليس بأكثر من ادعى إبراهيم دعوى، فعارضه بمثلها فانتقل إلى دعوى أخرى، وإن كان ما ذكره إبراهيم ثانية حجة، فهلا كان يعكس عليها ويقول: فليأت ربك بشمس من المغرب، فإن الآتي بها من المشرق حتى كان لا يبهت، قيل: قد تقدم أن ما يمكنه الله عن الأمم لا يكاد يستوفي القصة من أولها إلى آخرها، بل يورد نكتة، ويشير إليها إشارة وهو لم يستوف ذكر ما حاجه به كله، وقد تقدم أن نمرود لم يدع أني شخص وحشي موجد السماوات والأرض، وإنما كان ذلك على أحد الوجهين المتقدم ذكرهما، وكان قد ادعى أن كل ما هو داخل تحت قدرته، فهو أو مثله أو قريب منه داخل تحت قدرتي، فقال إبراهيم: ربي الذي يحي ويميت فقال أنا أحي وأميت، فأخرج رجلين من الحبس، فخلى أحدهما، وقتل الآخر، فقال: هذا أحياه وهذا أماته، وقد كان إبراهيم يمكنه أن يزيد أن الذي ادعاه لربه ليس هو الجنس الذي ادعيته لكن عدل إلى فعل ليس في طرق البشر هو ولا قريب منه ولا ما يشاركه اسما، مقال، قد ثبت باتفاق أن الله يحرك الشمس من المشرق، فحرك أنت تحريكا من المغرب، فلم يجد شيئا يدعيه كما ادعي في الأحياء والإماتة، فبهت حينئذ، وظهر عجزه إذ لم يكن من جنس إطلاع الشمس وإغرابها شي ممكن للملوك كما ادعي الإحياء والإماتة، ولم يمكنه أن يعكس ذلك، فقد كان أقر بالباري، وإنما كان يدعي أنه يفعل فعله،\nإن قيل: أليس العدول من حجة إلى حجة يعده أهل الجدل انقطاعا؟ فما وجه ما فعل إبراهيم؟\nقيل: أما أولا، فما ذكره إبراهيم كان معارضة، وذاك أن الكافر ادعي أن في وسعه أن يفعل كل جنس من الفعل يفعله الباري- عز وجل، وذلك ادعاء حكم موجب كلي، والكلي ينقض بالجزئي، نحو أن يقال: كل إنسان كاتب، فمتى وجد إنسان شرير كاتب فقد ظهر كدبه، وللمعارض إذا أراد المناقضة أن ينتقل عن مثال خفي إلى مثال جلي، ولا يكون ذلك منه انتقالا، وهذا باب قد أحكمه أهل الجدل، على أن ذلك لو كان ابتداء حجة، لم يكن على شرط أهل النظر بمذموم، فالحجج الجدول عليما ضربان.\n⟦1:539⟧\nحجة يذكرها، ثم يتركها لظهور فسادها، وذلك مما لا يرتضيه أهل النظر وحجة يذكرها، فيقصر فهم سامعها عن إدراكها، أو يكثر مشاغبته فيها، فيعدل عنها إلي ما هو أوضح، إذ كان كل يتبين الحق وإزالة الشبهة، وهذا ليس بمذموم، وقوله: ﴿أَنۡ ءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ﴾⟪2:258⟫ قال بعضهم: أراد إبراهيم لأن الله تعالى لا يؤتي الملك الكفرة، لأن ذلك مفسدة ينزه الله تعالى عنها، وأكثر المفسرين على أنه النمروذ وذاك أن السلطان من الأغراض الدنيوية، كالمال، والجاه، والأولاد، وذلك مما يؤتي المؤمن والكافر امتحانا واختبارا ...\nإن قيل: أليس قلت: إن الملك اسم لما فيه العدالة، فكيف يصح أن يقال ذلك لما يتوارد للكافر؟\nقيل: إن الملك الحقيقي الذي يجوز للإنسان المتسمي به هو ذاك لكن الناس يستعملونه فيمن يتسلط على الناس على أي وجه كان فتسمية الله تعالي إياه بذلك إنما هو على زعمه، وزعم أتباعه، كقوله: ﴿ذُقۡ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡكَرِيمُ﴾⟪44:49⟫ فسماه عزيزا لا بالحقيقة لكن على ما كان يتسمى به ...\nإن قيل: كيف قال: ﴿وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ﴾⟪2:258⟫، والظالم أولى بأن يهدى؟\nقيل: قد تقدم أنواع الهداية وأحوالها، وأنه قد يراعى في إطلاقها مبدؤها تارة، فتستعمل في الجميع الذي يمكنهم الاهتداء، وعلى ذلك قال ﴿وَأَمَّا ثَمُودُ فَهَدَيۡنَٰهُمۡ فَٱسۡتَحَبُّواْ ٱلۡعَمَىٰ عَلَى ٱلۡهُدَىٰ﴾⟪41:17⟫، ومرة يعتبر منتهاها الذي هو الاهتداء، فيقال: \" هدي الله المؤمنين \"، وعلى هذا قوله تعالي: ﴿فَمَن يُرِدِ ٱللَّهُ أَن يَهۡدِيَهُۥ يَشۡرَحۡ صَدۡرَهُۥ لِلۡإِسۡلَٰمِۖ﴾⟪6:125⟫ فقوله: ﴿لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ﴾⟪2:258⟫، أي: لا يقبلون منه هدايته لهم، وإذا لم يقبلوا منه لم يعطهم، وإذا لم يعطهم فهو لم يهدهم، وأيضا فالظلم هاهنا مناف للهداية، فإنه جحود ألاء الله، والامتناع من قبولها والهداية تقتضي تحري العدالة، فإذا الهداية والظلم\n⟦1:540⟧\nكالمتضادين لا يجتمعان ...\nإن قيل: لم أفرد النور وجمع الظلمة، قيل: لما كان النور عبارة عن الحق، والحق من حيث ما هو حق شي واحد لا يتنافى ولا يتناقض، والباطل من حيث ما هو باطل يتضاد ويتعاند صار فيه كثرة، ولهذا شبه الحق بالمقرطس من المريء في أنه واحد واحد، والخطأ ما عداها وهو كثير بلا نهاية، فلذلك أفرد النور وجمع الظلمة ...\nقوله تعالي:"}, {"a": [259], "v": 1, "p": 540, "ev": 1, "ep": 544, "sid": 541, "t": "﴿أَوۡ كَٱلَّذِي مَرَّ عَلَىٰ قَرۡيَةٖ وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحۡيِۦ هَٰذِهِ ٱللَّهُ بَعۡدَ مَوۡتِهَاۖ فَأَمَاتَهُ ٱللَّهُ مِاْئَةَ عَامٖ ثُمَّ بَعَثَهُۥۖ قَالَ كَمۡ لَبِثۡتَۖ قَالَ لَبِثۡتُ يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖۖ قَالَ بَل لَّبِثۡتَ مِاْئَةَ عَامٖ فَٱنظُرۡ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمۡ يَتَسَنَّهۡۖ وَٱنظُرۡ إِلَىٰ حِمَارِكَ وَلِنَجۡعَلَكَ ءَايَةٗ لِّلنَّاسِۖ وَٱنظُرۡ إِلَى ٱلۡعِظَامِ كَيۡفَ نُنشِزُهَا ثُمَّ نَكۡسُوهَا لَحۡمٗاۚ فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعۡلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ﴾⟪2:259⟫\nالآية (259) - سورة البقرة.\nالخو: خلو الوعاء، يقال: خلت الدار، تخوي خواء، وخوي النجم وأخوى إذا لم يكن منه عند سقوطه مطر تشبيها بذلك، وأخوي أبلغ من خوي، كما أن أسقي أبلغ من سقى، وخوي جوف فلان خوي، والتخوية: ترك ما بين الشيئين خاليا ...\nوالعرش: ما ارتفع من البناء، ويقال ذلك للسقف والسطح، وسمي السرير به تشبيها، أو عبر به عن أمر الإنسان، وقيل: استوى عرشه، وتل عرشه، والتعريش بناء ذلك وبه شبهه تعريش الكرم، وسمي المعررش منه عريشا، وقيل: عرش الحمار إذا رفع رأسه وجعله كعرش، وعرشان الفرس شعر عرفه تشبيها بعريش الكريم ...\nوالعام: مدة تعوم الشمس في أفلاكها المختصة بها، وذلك اعتبارا بنحو ما قال- عز وجل- ﴿وَكُلّٞ فِي فَلَكٖ يَسۡبَحُونَ﴾⟪36:40⟫ والاعتيام اختيار الشيء، وأصله أن يسير الإنسان كسابح فيه يتناول ما يريد.\n⟦1:541⟧\nولهذا قال الشاعر\nوكنت في نعمائه سابحا ..\nوالحمار سوي للونه اعتبارا بعامة جنسه، لأن الوحشيات منها، وكثيرا من الإنسيات حمر، فسمي بذلك كما سمي العجم حمرا، والعرب سودا، لكون أكثرهم كذلك، وحمار السرج، والحمارة لحجر عظيم تشبيها بالحمار في المهيئة، والحمرة: طائر أحمر اللون، وحمارة القيظ، أشد ما يكون حرا تشبيها بالجمر المتوقد لونا، والنشز من نشزك الثوب، ونشز الريح العرف، وقاره تعدي نشر، ومصدره الناشر كقوله تعالي «يين بشرا بين يدي رحمته»، وتارة لا يعدي، ومصدره النشور، كقوله- عز وجل- ﴿وَإِلَيۡهِ ٱلنُّشُورُ﴾⟪67:15⟫، ويقال: أنشره، كأنه جعل له نشرا، كقولك: (أسقاه: حبال له سقيا، ونشر الخشب، تشبيها بذلك، لجعل أجزاء الخشب منشورة، وإذا قرئ \" ننشزها \" فمعناه: نرفعها من النشز، أي المرتفع من الأرض، ومنه نشوز المرأة أن تطيح ببصرها إلى بشر صارفة له عن زوجها.\nكقول الفرزدق:\nإدا جلست عند الإمام كأنها\nبها رفقة من ساعة يستحيلها\n⟦1:542⟧\nوكقول الأخر:\nإذا الليل عن نشز تخلى رميته\nبأمثال أبصار النساء القواري\nقوله: \" لم يتسنه \": أي لم يتغير بمرور السنين عليه، وذلك من لغة من يجعل المحذوف من السنة الهاء (سينهه وسانهه)، وقيل هو من \" سانيت \"، والهاء للاستراحة، وعلى هذا يجب أن يحذف إذا وصل الكلام كذا، على قول من قال: المسنون: المتغير، ويقال: يتسنى، وأصله يتسنن فعلت تخفيفا، كقوله:\n\" تطنيت، وتعضيت، وتسريت \"\nإن قيل: ها الذي شبه بالذي مر على قرية؟ وعلى ماذا عطف؟ قيل: قد قال بعضهم: إن ذلك متعلق بما بعده، وهو قوله: ﴿وَإِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّ أَرِنِي كَيۡفَ تُحۡيِ ٱلۡمَوۡتَىٰۖ﴾⟪2:260⟫ ﴿كَٱلَّذِي مَرَّ عَلَىٰ قَرۡيَةٖ﴾⟪2:259⟫، ودلك بعيد لفضل \" وإذ \" بينهما، وقيل: الكاف زائدة، وليس بشيء والوجه أن الكاف ههنا ليس للتشبيه المجرد بل هو للتحديد والتحقيق كما هو في قولك الاسم كزيد وعمر وعلي أنه وإن جعل للتشبيه، فعلى سبيل المثل والمشبه غير مذكور، كما أنه غير مذكور في قولهم كالمهورة إحدى خدمتيها، ويحتمل أن تكون الآية من كلام إبراهيم معطوف على ما تقدم، وهو أنه لما قال للكافر: ﴿فَإِنَّ ٱللَّهَ يَأۡتِي بِٱلشَّمۡسِ مِنَ ٱلۡمَشۡرِقِ فَأۡتِ بِهَا مِنَ ٱلۡمَغۡرِبِ﴾⟪2:258⟫، قال له بعد: ﴿أَوۡ كَٱلَّذِي مَرَّ عَلَىٰ قَرۡيَةٖ﴾⟪2:259⟫، أي إن كنت تحي فأحي كما أحيا الله وصفه في هذه الآية ..\nويحتمل أن تكون آية مستأنفة، وضرب الله مثلين لشيئين أحدهما في ادعاء الربوبية، وهو ما تقدم، والثاني في إنكار البعث، وهو هذه، ويكون في قوله: ﴿كَٱلَّذِي﴾⟪2:259⟫ في موضع الجر على ما تقدم،\n⟦1:543⟧\nكأنه قال: (وألم تر إلى الذي حاج .. ) إلى مثل الذي مر على قرية،\nفإن قيل: فهل في تخصيص القصة الثانية بحرف التشبيه، وإخلاء الأولى منه فائدة؟\nقيل: بلى، فإن ادعاء الربوبية إنما قل في الناس، حتى إنه لم يعهد ذلك إلا في نفس أو نفسين وقال: (ألم ترى إلى الذي) والتشكل في الإحياء، من الجم الغفير، فنبه بقوله: ﴿أَوۡ كَٱلَّذِي مَرَّ﴾⟪2:259⟫ تنبيها أنه نظر إليه وإلى مثاله، وجعل نالك مثلا لمن نحى نحوه كقولك للكافر: كفلان، فتأتي بواحد على سبيل المثال، ولما ذكر تعالي إخراجه المؤمنين من الظلمات إلى النور، جعل اعتبار ذلك هذين، كأنه قال اعتبران تثبيت إبراهيم وإخراجه له من ظلمه الكفر إلى الإيمان مما جعلت له من الحجج، وإن شئت فيمن أخرجته من شبهة البعث بما جعلت ، له من العيان، والذي مر على القرية، قيل كان عزيزا عن قتادة والربيع، وقيل: \" كان أرمنينا عن وهب، وروي أنه مات ضحى وبعث قبل غروب الشمس بعد مائة عام، وقيل له: كم لبثت؟\nقال: لبثت يوما، فلما نظر إلى الشمس قال: أو بعض يوم، وقيل: بدأ تعالي بعينيه، فنفخ فيهما، ثم بعظامه، فأنشزها، ثم وصل بعضها ببعض، فنظر إلى حماره، وأجزاؤه تجئ من سهل وجبل، حتى اجتمعت فاتصل بعملها بعضها، وكسى لحمه، وجرى فيه الروح، فقام ينهق، فقال: أعلم: أي اعترفت بقدرة الله تعظيما لف، ومن قال: أعلم، فقد قليل: هو من قول الله عز وجل- له، وقيل: هو من قوله وقد خاطب به نفسه على طريق التبكيت، وقال بعض الناس بعزوه إلي بعض الأئمة أن الإشارة بالإحياء والإماتة إلى العلم والجهل، ومعنى القرية الرجال، بدلالة قوله: ﴿وَكَأَيِّن مِّن قَرۡيَةٍ عَتَتۡ عَنۡ أَمۡرِ رَبِّهَا﴾⟪65:8⟫، وقوله: ﴿وَتِلۡكَ ٱلۡقُرَىٰٓ أَهۡلَكۡنَٰهُمۡ لَمَّا ظَلَمُواْ﴾⟪18:59⟫ وقوله: ﴿وَسۡـَٔلِ ٱلۡقَرۡيَةَ﴾⟪12:82⟫، وجعل الخوى حلوا ينم\n⟦1:544⟧\nعن العلم والإيمان، وكذلك الإماتة والاحياء، إفادته العلم والإيمان، نحو قوله تعالى: ﴿ٱسۡتَجِيبُواْ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمۡ لِمَا يُحۡيِيكُمۡۖ﴾⟪8:24⟫ وقوله تعالي: ﴿أَوَمَن كَانَ مَيۡتٗا فَأَحۡيَيۡنَٰهُ وَجَعَلۡنَا لَهُۥ نُورٗا﴾⟪6:122⟫ الآية، قال: وكان قد رأي قوما متناهين في ألبعد عن العلم والإيمان، فاستبعد رجوعهم إلى الحق، فقال: ﴿أَنَّىٰ يُحۡيِۦ هَٰذِهِ ٱللَّهُ﴾⟪2:259⟫ أي: أني يفيدهم الإيمان، فأماته الله مائة عام، ثم أحياه، وأعلمه أن الذي يقدر على إحياء الرمم عن الموت الحيواني لقادر على إحياء النفس الميتة بالجهل ...\nقوله- عز وجل: -"}, {"a": [260], "v": 1, "p": 544, "ev": 1, "ep": 548, "sid": 545, "t": "﴿وَإِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّ أَرِنِي كَيۡفَ تُحۡيِ ٱلۡمَوۡتَىٰۖ قَالَ أَوَلَمۡ تُؤۡمِنۖ قَالَ بَلَىٰ وَلَٰكِن لِّيَطۡمَئِنَّ قَلۡبِيۖ قَالَ فَخُذۡ أَرۡبَعَةٗ مِّنَ ٱلطَّيۡرِ فَصُرۡهُنَّ إِلَيۡكَ ثُمَّ ٱجۡعَلۡ عَلَىٰ كُلِّ جَبَلٖ مِّنۡهُنَّ جُزۡءٗا ثُمَّ ٱدۡعُهُنَّ يَأۡتِينَكَ سَعۡيٗاۚ وَٱعۡلَمۡ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ﴾⟪2:260⟫\nالآية (260) - سورة البقرة.\nالاطمئنان: السكوت، واطمأن، وتطامن يتقاربان لفظا ومعنى من مكان مطمئن ...\nقيل: ويدل على ذلك أنه قال في مكان أخر (مخبتين)، والمخبت: المطمئن من الخبت، أي المطمئن من الأرض، وطار، وطير، نحو راكب وركب ، و \" تطايروا \" أي تفرقوا، استعارة وفجر مستطير، وغبار مستطار، خولف بين بيانهما لاختلاف التصورين في كون الفجر فاعلا والغبار مفعولا وفرس مطار يقالك للسريع، ويقال لجديد، الفؤاد كأنه أطير فلبه، كقولهم شهم ومروع وقوله: ﴿وَكُلَّ إِنسَٰنٍ أَلۡزَمۡنَٰهُ طَٰٓئِرَهُۥ﴾⟪17:13⟫ أي ما يدمن أفعاله وصرته أصوره، أي أملته وصرته: قطعته صورة صورة، وقيل: صرت، وصرت: لغتان، والصوار سمي اعتبارا بالقطع كالقطيع والصرمة والصور النخل الصغار، إما لانقطاعها عن لحوق الكبار، أو كأنها مقطوعة في نفسها، والصور قيل: سمي لأن فيه صور الناس\n⟦1:545⟧\nكلها وقيل: بل لإعادة الصورية، وذكر أبو بكر النقاش المقرئ أنه قرئ (فصرهن) بضم الصاد وتشديد الراء وفتحها من الصر، أي الشد، ومنه الصرة، وقال: قد قرئ (فصرهن) بكسر الصاد وفتح الراء وتشديدها من الصرير من الصوت أي، صح بهن وروي أن إبراهيم مر على ساحل البحر بميتة، والسباع والطيور والحيتان يتوزع لحمها، فتفكر، فسأل الله تعالى إحياء مثله فأمره تعالى أن يأخذ أربعة طيور فيقطعها فيخلطها لحومها وريشها، ويبددها على جبال (خزاجرا) ثم يدعوها، ففعل ذلك، فاجتمعت كلها، فتبين إبراهيم ما اعتراه فيه الشبهة وقال بعضهم:\nأمره أن يأخذ أربعة طيور، فيضعهن على أربعة جبال ومعنى لجزء واحد منها، ثم يدعوها فتجتمع لديه، فأشار إلى أنه كاجتماع هذه الطيور لديك كذلك يجتمع من الجوانب الأربع الأموات قال، ولو كان (فصرهن) قطعهن، لما قال: إليك لأن ذلك لا تعدي بالباء ..\nإن قيل: لم لما سأله إبراهيم، أراد ذلك على أقرب الوجوه لما سأله عزير، أماته مائة عام حتى تفرقت أوصاله ونخرت عظامه.\nقيل قد ذكر بعض الصوفية أن إبراهيم كان خليلا فمجاز له أن ينبسط لما سلف له من قدم صدق، فلما سأله ذلك، أعطاه سؤله، في الوقت على أقرب الوجوه ولم يكن العزير من الخلة ما يجوز هذا الانبساط قلما أقدم أبلاه الله تعالى في نفسه، وأراه ذلك في ذاته، ولأن إبراهيم تضرع وسأل وقال أرني، وغيره أخرج الكلام مخرج المنكر المتعجب من قدرة الله عز وجل وقال: ﴿أَنَّىٰ يُحۡيِۦ﴾⟪2:259⟫ ولا يخفى ما بين اللفظين من الضراعة والغلظة، ولهذا ختم آية عزير بقوله: ﴿أَعۡلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ﴾⟪2:259⟫ وآية إبراهيم بقوله ﴿وَٱعۡلَمۡ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ﴾⟪2:260⟫ وقال الأصم: تفهموا عن الله حجج\n⟦1:546⟧\nالرسل، إن عيسى كان يحي الموتى بإذن الله ويريه العباد ليثبت بذلك رسالته ويخلق من الطين كهيئة الطير، فينفخ فيها فتكون طيرا بإذن الله) وإبراهيم كان يطلب أن يرى ما كان عيسى يريه قومه قال وفي هذا دليل أن الله لله عز وجل منع بعض الرسل من الآيات ما أعطاه بعضا.\nإن قيل إن كان إبراهيم في هذه الحال شاكا في البعث فلم لما قيل له ﴿أَوَلَمۡ تُؤۡمِنۖ قَالَ بَلَىٰ﴾⟪2:260⟫، والشاك في الشيء لا يجوز أن يكون مؤمنا به وإن كان موقنا فلا معنى لقوله: ﴿وَلَٰكِن لِّيَطۡمَئِنَّ قَلۡبِيۖ﴾⟪2:260⟫ فلا اضطراب للقلب مع اليقين، فإذا هذا قول متناقض قيل: إن إبراهيم كان موقنا بالبعث أنه كائن للاستدلال أولا، وللوحي ثانيها وإنما التمس غاية التفسير وهو العيان الذي تنقطع عنده الخواطر كلها، فالخاطر ضربان، خاطر في ثبوت الشيء ونفيه، وخاطر في كيفية ثبوته، والأول يزول بالخبر والثاني لا يزول إلا بالعيان، وهذا هو حال إبراهيم وقيل: اليقين ثلاثة أضرب: علم اليقين، وعين اليقين، وحق اليقين فعلم اليقين: ما وصول إلينا على سنة رسول الله - صلى الله عليه وسلم - وعين اليقين: ما وصل إلينا بأنوار هدايته، وحق اليقين: ما اجتمع فيه الأمران، وبه تزول عوارض الخواطر عن جملته وتفاصيله وقيل: إن إبراهيم كان طلب كذلك لأن قومه سألوه وذلك كما قيل في سؤال موسى، حيث قال: ﴿أَرِنِيٓ أَنظُرۡ إِلَيۡكَۚ﴾⟪7:143⟫ وقيل، إن نمرود كان ممن يعتمد المحسوس، ولما قال له إبراهيم: ﴿رَبِّيَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُ﴾⟪2:258⟫ قال له: أرأيت ذلك بحاستك؟ فعدل إلى غيره من الحجج إذ لم يكن يمكنه أن يدعي عيان ذلك ثم سأل الله بعد ليريه ليمكنه أن يخبر به، وقيل: إن إبراهيم أحب أن يريه الله إحياء نفسه معراة من الأصل والزنا والفحش والحرص فبين الله أن ذلك لا سبيل إليه بأدلة الإنسان في هذا العالم، ومخلوق خلقه للتكليف، وأمره أن يأخذ أربعة من الطير، نسرا: إشارة إلى طول الأمل، وطاوسا: إشارة إلى زينة الدنيا، وغرابا: إشارة إلى الفحش النفسي، وديكا: إشارة إلي الحرص، وقال: قطعهن ووزعهن على جبال، ثم صرهن، فقد عادت إليك إشارة إلى أن هذه القوى وإن اجتهدت في إفنائها، فلا سبيل إلى إزالتها مادامت في دار الدنيا، وقيل: إن إبراهيم لما رشد\n⟦1:547⟧\nللرسالة وإرشاد البرية ورأي قوما في نهاية الجهالة والكفر، استعظم رجوعهم إلى الحق، فقال: ﴿أَرِنِي كَيۡفَ تُحۡيِ ٱلۡمَوۡتَىٰۖ﴾⟪2:260⟫ أي ترشد الضلال الذين هم كالموتى، وأراد كيف أحيي، ولكن نسب الفعل إلى الله - عز وجل - على طريقة ما تقدم أن أولياء الله - عز وجل - يتحرون في أفعالهم - رضى الله لله ويرون أفعالهم فعله، ولهذا قال عليه الصلاة والسلام فيما رواه عنه - عز وجل - (حتى أكون عينه التي يبصر بها)، ولأن الأفعال المحمودة للعباد كلها منسوبة إلى الله من حيث أنه سبب إيجادها، ولهذا قال: ﴿ءَأَنتُمۡ تَزۡرَعُونَهُۥٓ أَمۡ نَحۡنُ ٱلزَّٰرِعُونَ﴾⟪56:64⟫، فعلى هذا معنى \" أرني كيف تحيي الموتى \" أي: كيف حال ما أمرتني به، وبعثتني فيها فقال له أولم تؤمن، أي أو لم تتحقق أنك ستهدى لذلك؟، فقال: بلى، ولكن أريد ما أسكن إليه في أن تجاب دعوتي، فقال: خذ أربعة من الطير، إشارة إلى قلع هذه القوى من نفسك وسمى بذلك كل موتان الفؤاد كالجبل فليس يعسر عليك ذلك ..\n\" والله أعلم بالصواب \" ..\nإن قيل: ما معنى قول النبي - صلى الله عليه وسلم - في هذه الآية: \" نحن أحق بالشك من إبراهيم \".\n⟦1:548⟧"}, {"a": [261], "v": 1, "p": 548, "ev": 1, "ep": 551, "sid": 549, "t": "قوله - عز وجل:\n﴿مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتۡ سَبۡعَ سَنَابِلَ فِي كُلِّ سُنۢبُلَةٖ مِّاْئَةُ حَبَّةٖۗ وَٱللَّهُ يُضَٰعِفُ لِمَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ﴾⟪2:261⟫ الآية (261) - سورة البقرة.\nيقال النبت لما له نمو في أصل الحلقة يقال تنبت الصبي والشعر والسن وفلان حسن النية ويستعمل النبات فيما له ساق، وما ليس له ساق وإن كان في التعارف قد يختص بما لا ساق له، وأنبت الغلام إذا راهق، كأنه صار ذا نبتة وفلان في منبت خير كناية عن الأصل، والسنبلة فيعلة من السبل يقال: أسبل الزرع، وسنبل، من أصله السبيل وقد تقدم أن سبيل الله ليس بمقصور على الجهاد، بل هو لكل ما يتوصل به إلى الله عز جل، والمائة عدد معروف يقال: أماءت الدراهم وألفت وإمايتها وألفتها ..\nإن قيل: كيف تعلق هذه الآية بما قبلها؟ قيل: إن ذلك متعلق بقوله: ﴿مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ﴾ وما بينه وبين هذه الآية، اعتراضات مرغبة للإنسان في فرضه من حث على قناعة هي أس الجود، وذكر عظمة المستقرض وإرشاد لمن يستقرض منهم، وبين في يده أن فرضه هو الإنفاق في سبيله وأن مضاعفته هو بأن يجعل للواحد سبع مائة وأنه يضاعف مع ذلك لمن يشاء مضاعفة لا يضبط عدها، ولا يعرف حدها ..\nإن قيل:\nكيف قال في موضع: \" يضاعف \"، وفي موضع: ﴿مَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ عَشۡرُ أَمۡثَالِهَاۖ﴾⟪6:160⟫ وقال هاهنا ما يدل على أنه يحادي بواحد سبع مائة، قيل: في ذلك طريقتان: إحداهما أن الخيرات تختلف باختلاف العالمين واختلاف نياتهما والثاني: أن تختلف باختلاف الأعمال فالأول: هو أن الناس فيما يتحرونه من أفعال الخير بالقول المجمل ثلاثة أضرب على ما قصد تعالى من ظالم ومقتصد وسابق أما الظالم: فالمتحري للخير مخافة سلطان ومذمة إنسان وتخويف عالم إياه من النار ونحو\n⟦1:549⟧\nذلك ..\n، وأما المقتصد: فالمتحري للخير مخافة عقاب الله ورجاء ثوابه من حيث ما قد تحقق وعده ووعيده، وأما السابق: فالمتحري للخير قصدا لوجه الله خالصا وثوابهم يختلف باختلاف مقاصدهم ولهذا قال عليه الصلاة والسلام في السابقين حاكيا عن الله عز وجل - (أعددت لعبادي الصالحين ما لا عين رأت، ولا أذن سمعت ولا خطر على قلب بشر) الخبر.\nوالثاني.\nوهو أن يختلف باختلاف الأعمال وبيان ذلك أن السخاء أفضل أفعال العباد بدلالة قول النبي - صلى الله عليه وسلم -: \" السخاء شجره من أشجار الجنة، أغصانها متدليات في الدنيا فمن أخذ بغصن من أغصانها أداه إلى الجنة ، والبخل شجرة من أشجار النار، فمن أخذ بغصن من أغصانها أداه إلى النار \"\nوقيل لبعض الحكماء:\n\" أي شيء من أفعال العباد أشبه بفعل الله \"؟\nفقال: \" السخاء، وأفضل الجود ما كان عن ضيق \" ..\n⟦1:550⟧\nولهذا قال الشاعر:\nليس العطاء من الفضول سماحة ...\nحتى تجود وما لديك قليل\nوقد علم أن أصحاب النبي - صلى الله عليه وسلم - كانوا مضيفين سيما في ابتداء الإسلام وأفضل الإنفاق ما يقصد به وجه الله لعز وجل -، وأفضل ما يقصد به وجهه ما يجعل في سبيل الله، وأفضل سبيل ينفق فيه ما كان أكثره غنى، وقد علم أنه لا جهاد أكبر من جهاد النبي - صلى الله عليه وسلم - ولا قوم أكفر ممن كان يحاد بهم ولا زمان أحوج إلى محاربتهم من زمانه وكل وأحد من هذه الخصال يجري مجرى فعل يستحق مثوبة محددة، فعظم الله تعالى أمر الإنفاق في سبيله في زمانه، وجعل له من الثواب ما لم يجعل لغيره من الأعمال، ووجه ثالث وهو أن الإنسان متى تحرى فعل الخير على ما يجب وكما يجب يدعوه ذلك إلى أن يزيد في فعل الخير فلا يزداد، حتى إنما يصير مثل ملك فيه الفضيلة وبازدياده في الإيمان وفعل الخيرات يزداد ثوابه، فحيث ما ذكر التضعيف، فأشار إلى الحالة الأولى وحيث ما ذكر عشرة أمثالها وسبعمائة فإلى الأحوال المتوسطات وحيث ما ذكر، ﴿وَٱللَّهُ يُضَٰعِفُ لِمَن يَشَآءُۚ﴾⟪2:261⟫، فإلى المنتهيات والغايات وأنها لا يحصرها عدد كما قال: عليه الصلاة والسلام: \" ما لا عين رأت ولا أذن سمعت \".\n⟦1:551⟧"}, {"a": [262], "v": 1, "p": 551, "ev": 1, "ep": 552, "sid": 552, "t": "قوله - عز وجل:\n﴿ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتۡبِعُونَ مَآ أَنفَقُواْ مَنّٗا وَلَآ أَذٗى لَّهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ﴾⟪2:262⟫ الآية (262) - سورة البقرة.\nالمن على ضربين: أحدهما ما يوزن به والأكثر منا بالتخفيف، والثاني قدر الشيء ووزنه، ومنه المنة، فإنها تستعمل على ضربين، أحدهما: اسما للعطية - لكونها ذات قدر بالإضافة إلى سائر الأفعال، وذلك لما تقدم أنفا في صفة الجود وأنه أشرف فضيلة، والثاني: اسما لقدر العطية عند معطيها واعتداده بها، وهو المنهي عنه بقوله ﴿لَا تُبۡطِلُواْ صَدَقَٰتِكُم بِٱلۡمَنِّ وَٱلۡأَذَىٰ﴾⟪2:264⟫، وقوله - عليه الصلاة والسلام: \" والامتنان بالمعروف فإن ذلك مما يبطل الشكر ويمحق الأجر \"، وقيل: \" تعداد المنة من ضعف المنة \"، والمنة تهديه للصنيعة، وللعطيه متى استعظمها المعطى فشكر منه، ومتى استعظمها المعطى، فهدم منه، فقوله: ﴿ٱلَّذِينَ يُنفِقُونَ﴾⟪2:262⟫ يجوز أن يكون خبر ابتداء مضمر أي الذين مثل إنفاقهم كمثل حبة منهم الذين ينفقون أموالهم، ويكون قوله: ﴿لَّهُمۡ أَجۡرُهُمۡ﴾⟪2:262⟫ في موضع الحال ويجوز أن يكون \" الذين \" هذا يفسر \" الذين \" المتقدم ويكون الذين ابتداء وما بعده خبرا، وقوله: ﴿وَلَآ أَذٗى﴾⟪2:262⟫ الأظهر الأكثر أنه معطوف على قوله: \" منا \"، وهو أعم منه لأن كل من أذى، وليس كل أذي منا، وقيل: هو أن يظهر المسئول تبرما بالسائل، نحو أن يقول: \" أراحني الله منك \"، أو: \" من أبلاني بك \" فعلى هذا قوله: ﴿لَّهُمۡ أَجۡرُهُمۡ﴾⟪2:262⟫ استئناف، وقوله: ﴿لَا يُتۡبِعُونَ مَآ أَنفَقُواْ مَنّٗا﴾⟪2:262⟫ تام، وقوله: \" ولا أذى لهم \" كلام مستأنف من صفة المعطى كأنه قيل: \" الذين ينفقون ولا يمنون، ولا ينادون بالإنفاق، فإن تمام فضيلة المنفق في سبيل الله أن يصير سلس الطبع بالعطاء، مستلذا، يصرف المال إلي الوجوه المحمودة \"، كما روى أن من الرجل محمودا حتى يكون ما ينفق في سبيل الله أحب إليه مما تركه، وروي هشام بن عروة عن النبي - صلى الله عليه وسلم - من أعطى عطية وهو طيب النفس بها بورك فيها للمعطي والمعطى \".\n⟦1:552⟧\nقال بشار:\nليس يعطيك للرجاء والخو ...\nف ولكن يلذ طعم العطاء\nوالبخيل يتألم بما يعطي غيره، فضلا عما يعطيه هو، ولهذا قيل أن \" الحر يعطي واللئيم يألم إسته \".\nوقوله: ﴿أَجۡرُهُمۡ عِندَ رَبِّهِمۡ﴾⟪2:262⟫ ضمن ضمان يلي، وفي يؤمن إخلافه وإفلاسه، وقوله: ﴿وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ﴾⟪2:262⟫ ليس يراد به الخوف في الآخرة فقط، بل يريد مع ذلك الخوف الذي ابتلى به أبناء الدنيا الذين ينفقون بما في أيديهم دون ما في يد الله - عز وجل -، ويجوز أن يكون قوله: ﴿وَلَا خَوۡفٌ عَلَيۡهِمۡ﴾⟪2:262⟫ من: \" خفت على فلان \" أي أشفقت عليه أي : لا إشفاق عليهم لما هم فيه من النعيم ﴿وَلَا هُمۡ يَحۡزَنُونَ﴾⟪2:262⟫، فعلى هذا قوله ﴿أَجۡرُهُمۡ عِندَ رَبِّهِمۡ﴾⟪2:262⟫ إلى أخر الآية، ذكر مالهم من الثواب ويجوز أن تكون الآية كلها وصفا للإنفاق في سبيل الله وبيان ذلك أن حق المنفق في سبيل الله أن تطيب به نفسه، وأن لا تتعقبه بالمن وأن لا تشفق من فقر تناله من بعد، بل تثق بكفاية الله - عز وجل -، ولا يحزنون إن يناله فقر، وبين تعالى أن ما تقدم ذكره من مجازاة واحد بسبع مائة هو لن هذا وصفه .."}];
